(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c60"]=[{"id":"00007911","register_sub_id":"101","register_pk":"108891","name":"芦田家住宅主屋","kana":"あしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市食満3-492","lat":34.76240046,"lng":135.43528439,"geo_status":"db","era":"昭和6／昭和後期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0434","desc":"敷地の西北に建つ、桁行１６ｍ梁間１１ｍの木造つし２階建。入母屋造桟瓦葺、周囲に下屋庇をまわし北面中央に入母屋屋根を張り出す。西寄りに土間を設け、床上は六間取を拡張した形式になる。黒漆喰仕上げの真壁と、軸部や雨戸の弁柄塗のコントラストが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007911"},{"id":"00007912","register_sub_id":"101","register_pk":"108892","name":"芦田家住宅土蔵","kana":"あしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市食満3-492","lat":34.76224986,"lng":135.43545362,"geo_status":"db","era":"江戸後期／昭和後期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0435","desc":"敷地南東に建つ。桁行５．９ｍ梁間３．９ｍ、土蔵造２階建、東西棟の切妻造本瓦葺。御影石積の基礎上、竪板を高く張り、上部は軒裏まで白漆喰で塗り込め、母屋形を現す。北面中央に庇付の出入口を設け、２階西面に窓１ヵ所を開ける。標準的な土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007912"},{"id":"00007913","register_sub_id":"101","register_pk":"108893","name":"芦田家住宅納屋","kana":"あしだけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市食満3-492","lat":34.76225245,"lng":135.4353408,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0436","desc":"土蔵の西に隣接して建つ。桁行１２ｍ梁間５．８ｍの木造平屋建。切妻造桟瓦葺で、北面を葺き降ろし、半間通りの吹放ちを設ける。南面は半間ごとに柱を建て、真壁造で、腰を竪板張とし、横格子窓２ヵ所を開ける。簡素ななかに、穏やかな表情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007913"},{"id":"00003466","register_sub_id":"101","register_pk":"104456","name":"アメリカンハウス（旧ハムウェイ邸）","kana":"あめりかんはうす（きゅうはむうぇいてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区北野町3-57","lat":34.70082648,"lng":135.18934296,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"28 － 0123","desc":"神戸北野地区の洋館群の中に建つ。木造２階建，寄棟造で，東西に長い長方形平面の東南隅をやや突出させる。１階南側は３室続きのリビング・ダイニングとし，その西寄りに暖炉を設け，北側に台所を配する。２階には各居室を設ける。昭和初期の洋風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003466"},{"id":"00002809","register_sub_id":"101","register_pk":"103799","name":"荒井家住宅蔵及び納屋","kana":"あらいけじゅうたくくらおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市須磨区月見山本町1-3-8","lat":34.64840841,"lng":135.12317424,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦及び鉄板葺、建築面積25㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"28 － 0102","desc":"桁行５間，梁間１間半の細長い建物で，建設当初の屋敷構成を示す建物である。西３間の蔵は切石積基壇に建つ２階建の土蔵造，東２間の納屋は１階土間床で真壁造の２階建である。外壁はともに縦板覆いで連続するが，切妻造・桟瓦葺の屋根は段違いになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002809"},{"id":"00002808","register_sub_id":"101","register_pk":"103798","name":"荒井家住宅主屋","kana":"あらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市須磨区月見山本町1-3-8","lat":34.648273,"lng":135.12323,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積152㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"28 － 0101","desc":"須磨の海浜を望む好立地に，南面して建つ。木造２階建，桟瓦葺，入母屋造で，塔屋状の３階は震災後の増設。南と北の部屋を中廊下で処理した平面，開放性の高い開口部，床・棚・付書院や欄間など洗練された室内構成など，当時としても質の高い和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002808"},{"id":"00015211","register_sub_id":"101","register_pk":"530635","name":"池浦家住宅表門","kana":"いけうらけじゅうたくおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市翠ケ丘町139-1","lat":34.73735833,"lng":135.31661944,"geo_status":"db","era":"昭和8年頃／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口2.0m、袖塀付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0826","desc":"通りに北面する表門。切妻造桟瓦葺の軒端を銅板一文字葺とする腕木門で、板扉に大きな斫り目を施し、門戸上部は格子欄間とする。控柱は名栗仕上。落棟とする左右袖塀は斫り目付の竪板張で西側に潜戸を開く。簡素な構成ながら丁寧なつくりとした屋敷の表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015211"},{"id":"00015210","register_sub_id":"101","register_pk":"530634","name":"池浦家住宅主屋","kana":"いけうらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市翠ケ丘町139","lat":34.737225,"lng":135.31666111,"geo_status":"db","era":"昭和8年／平成7年・同29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0825","desc":"六甲山南麓の住宅地に位置する海運会社役員の洋館付住宅。西側和館はつし二階建で、良材を用いる端正な座敷は床、床脇、付書院を備える。東側洋館は二階建で、ステンドグラスのモチーフに船など、階段廻りにチーク材を用い、海運商らしい特徴を示す郊外住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015210"},{"id":"00016685","register_sub_id":"101","register_pk":"579169","name":"池本家住宅内蔵","kana":"いけもとけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市西区櫨谷町福谷字城ヶ谷661-1","lat":34.717723,"lng":135.039637,"geo_status":"db","era":"昭和4年／昭和47年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0869","desc":"主屋の北に位置する家財蔵。南面して建つ二階建切妻造平入桟瓦葺で、西に平屋を接続し、正面に廊下を付す。外壁は漆喰塗で北面は腰に焼杉板を高く張る。小屋は登梁形式で棟木から軒まで野地板を流板に張る。窓庇の袖壁に鏝絵を飾り、通りの景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016685"},{"id":"00016684","register_sub_id":"101","register_pk":"579168","name":"池本家住宅主屋","kana":"いけもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市西区櫨谷町福谷字城ヶ谷661-1","lat":34.717678,"lng":135.039753,"geo_status":"db","era":"大正前期／昭和47年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積166㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0868","desc":"明石川上流の農村集落に位置する旧醤油醸造販売業の主屋。敷地北寄りに南面して建つ二階建入母屋造桟瓦葺で周囲に下屋を廻らし、北面は西寄りを外に張出す。外壁黒漆喰塗。東は土間、西は食違いに４室を配す。南西の座敷は広大な庭に面し、眺望優れた主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016684"},{"id":"00016688","register_sub_id":"101","register_pk":"579172","name":"池本家住宅車庫(旧納屋)","kana":"いけもとけじゅうたくしゃこ（きゅうなや）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市西区櫨谷町福谷字城ヶ谷661-1","lat":34.717676,"lng":135.039933,"geo_status":"db","era":"大正前期／昭和4年、同中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0872","desc":"主屋の南東に位置する旧納屋。つし2階建片入母屋造桟瓦葺で、南西に下屋を付す。外壁は真壁で黒漆喰仕上とし、腰は竪板を高く張る。一階は土間、二階は板敷の一室で、小屋は太い地棟に束立とする。通りに面して円形の虫籠窓を開け、屋敷の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016688"},{"id":"00016687","register_sub_id":"101","register_pk":"579171","name":"池本家住宅外蔵","kana":"いけもとけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市西区櫨谷町福谷字城ヶ谷661-1","lat":34.717717,"lng":135.03989,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0871","desc":"主屋の東、長屋の南に続く道具蔵。2階建切妻造平入桟瓦葺で、西面南寄りに戸口を設け、庇を付す。外壁は漆喰で塗込め、腰は西は海鼠壁、東は焼杉板を高く張る。各階板敷の１室で小屋は登梁形式とする。窓小さく閉鎖的な外観で敷地東面の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016687"},{"id":"00016686","register_sub_id":"101","register_pk":"579170","name":"池本家住宅長屋及び旧炊事場","kana":"いけもとけじゅうたくながやおよびきゅうすいじば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市西区櫨谷町福谷字城ヶ谷661-1","lat":34.717785,"lng":135.039768,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造二階一部平屋建、瓦葺、建築面積75㎡","structure_material":"木造二階一部平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0870","desc":"敷地北東隅に位置する旧炊事場及び長屋。つし二階建の物置兼居室の北西に平屋建の旧炊事場を接続し、全体矩折平面とし、屋根は桟瓦を葺く。道に面した北・東側の外壁は真壁で、黒漆喰塗、腰は竪板を高く張る。円形の虫籠窓が特徴的で、通りの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016686"},{"id":"00016689","register_sub_id":"101","register_pk":"579173","name":"池本家住宅門及び塀","kana":"いけもとけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市西区櫨谷町福谷字城ヶ谷661-1","lat":34.717592,"lng":135.04004,"geo_status":"db","era":"昭和49年","year":1974,"year_source":"db","year_min":1974,"year_max":1974,"year_label":null,"structure":"門 木造、瓦葺、間口3.2m 塀 鉄筋コンクリート造、瓦葺、総延長30m、北・南木戸門付","structure_material":"門 木造","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0873","desc":"敷地東面南寄りに開く門と両脇に続く塀。門は切妻造平入桟瓦葺で、箱状の柱の頂部に冠木を渡し、３筋の腕木で軒桁を支持する斬新な形式。塀は花崗岩基礎に建つ、鉄筋コンクリート造桟瓦葺で、壁は内外ともモルタル塗仕上。重厚な屋敷景観を形成する門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016689"},{"id":"00012971","register_sub_id":"101","register_pk":null,"name":"石田家住宅主屋","kana":"いしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘二丁目235","lat":34.82767222,"lng":135.40099722,"geo_status":"db","era":"大正後期／昭和23年増築、昭和30年代改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"28 － 716","desc":"阪急雲雀丘花屋敷駅北側の住宅地にあり、主屋は南斜面の敷地中央に建つ。急勾配の入母屋造洋瓦葺で、南面両端に座敷、東面中央に玄関を突出し、東北隅に洋風応接間を付す。座敷や居室は数寄屋風の意匠でまとめる。近代住宅地開発初期の様相を伝える和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012971"},{"id":"00012972","register_sub_id":"101","register_pk":null,"name":"石田家住宅屋敷門","kana":"いしだけじゅうたくやしきもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘二丁目235","lat":34.82754444,"lng":135.40111944,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺及び銅板葺、間口1.6m、左右袖塀付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"28 － 717","desc":"敷地南面の中央に街路に面して建つ。薬医門形式、緩勾配の入母屋造桟瓦葺、周囲銅板葺で、本柱に磨き丸太を用い、門扉上の小壁に下地窓をあしらい、網代天井を張るなど数寄屋風の意匠でまとめる。近代住宅地中心部の閑静な街路景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012972"},{"id":"00009197","register_sub_id":"101","register_pk":"164750","name":"石堂家住宅井戸屋","kana":"いしどうけじゅうたくいどや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01329725,"lng":134.28560211,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、銅板葺、面積0.9㎡","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の南方、表門の近くに位置する。桁行1.2メートル梁間0.7メートル、切妻造銅板葺の本体の内部に石製の井戸枠を据える。本体正面に緩い曲線の唐破風屋根を差出して、水汲場を覆う。小規模ながら、丁寧なつくりの井戸屋で、旧家の暮らしぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009197"},{"id":"00009198","register_sub_id":"101","register_pk":"164751","name":"石堂家住宅表門","kana":"いしどうけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01326513,"lng":134.28565327,"geo_status":"db","era":"江戸末期／昭和62年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖付","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の南辺中央に東西棟で建つ。間口2.6メートルの一間薬医門で、左右に袖を付け西袖に潜戸を吊る。切妻造本瓦葺で、棟両端に棟飾瓦を置く。瓦当や蟇股に家紋の揚羽蝶をあしらい、木太い柱と大振りな瓦屋根が、旧家の屋敷構えに風格を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009198"},{"id":"00009196","register_sub_id":"101","register_pk":"164749","name":"石堂家住宅角屋及び西門","kana":"いしどうけじゅうたくかどやおよびにしもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01337815,"lng":134.28542246,"geo_status":"db","era":"明治後期／昭和56年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"角屋 木造2階建、瓦葺、建築面積112㎡ 門 木造、瓦葺、間口3.8m","structure_material":"角屋 木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の西辺中央に角屋が南北棟で建ち、南側に西門を構える。角屋は桁行16メートル梁行6.9メートル、木造2階建、入母屋造桟瓦葺。西門は桁行3.8メートル、切妻造桟瓦葺で、潜付きの一間板戸を片引きとする。建ちの高い納屋が屋敷地西面の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009196"},{"id":"00009195","register_sub_id":"101","register_pk":"164748","name":"石堂家住宅米蔵及び内蔵","kana":"いしどうけじゅうたくこめぐらおよびうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01341051,"lng":134.28590787,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積80㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の東方、敷地東辺に南北棟で建つ。桁行11メートル梁行5.9メートル、土蔵造2階建、切妻造桟瓦葺。上下階とも内部は2室で、南室を内蔵、北室を米蔵とする。下階各室の西面に出入口を、上階東面に窓を穿ち、旧家の屋敷構えを構成する大型土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009195"},{"id":"00009193","register_sub_id":"101","register_pk":"164746","name":"石堂家住宅主屋","kana":"いしどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01339005,"lng":134.28573655,"geo_status":"db","era":"江戸後期／昭和前期・昭和37年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、茅葺及び瓦葺、建築面積256㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"川沿いの敷地中央に南面して建つ。桁行22.7メートル梁間11.8メートル、木造平屋1部2階建、入母屋造茅葺。西側を土間とし、東側の床上部は前後に4室ずつ並べ、前列東端に奥座敷を配し、庭に面して縁を廻らす。播磨地方の大型民家の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009193"},{"id":"00009199","register_sub_id":"101","register_pk":"164752","name":"石堂家住宅中門","kana":"いしどうけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01329963,"lng":134.28578295,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、銅板葺、間口1.3m、左右土塀付","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の式台玄関の前方に南北棟で建ち、南北に土塀を延ばす。間口1.3メートルの一間薬医門、起り付の切妻造銅板葺で軒は疎垂木とする。土塀は主屋側と南側で高さを変え、1部透塀とする。小規模な門であるが、土塀とともに上質な庭空間を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009199"},{"id":"00009201","register_sub_id":"101","register_pk":"164754","name":"石堂家住宅東北塀","kana":"いしどうけじゅうたくとうほくべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01350295,"lng":134.28593371,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長7.9m","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"米蔵及び内蔵の東北隅から北方へ折曲がりに延びる高塀。延長7.9メートル、切妻造桟瓦葺。屈曲部から段々に高さを増して敷地背面の北塀に繋ぐ。壁は漆喰塗の真壁とし、腰に竪板を張る。米蔵と連続したつくりで、趣きのある屋敷景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009201"},{"id":"00009200","register_sub_id":"101","register_pk":"164753","name":"石堂家住宅南塀","kana":"いしどうけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01324878,"lng":134.28578467,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、総延長45m、門付","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の南面、表門の東西に延びる土塀で、東端の向座敷取付き部に間口0.8メートルの棟門を開く。巧緻な切込矧ぎの石積み上に築かれ、総延長45メートルを測り、壁は中塗りを表し、屋根は桟瓦葺とする。表門とともに、風格ある構えを形成している","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009200"},{"id":"00009194","register_sub_id":"101","register_pk":"164747","name":"石堂家住宅向座敷","kana":"いしどうけじゅうたくむかいざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県佐用郡佐用町大垣内823","lat":35.01329963,"lng":134.28591643,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積48㎡、渡廊下付","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の東南隅に南北棟で建つ。桁行8.5メートル梁間5.6メートルの木造平屋建、入母屋造桟瓦葺で周囲を下屋とする。主座敷と次の間の2室からなり、南西面に矩折れに縁を廻す。南面縁の高欄や欄間に繊細な意匠を用いる、開放的で瀟洒なつくりの離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009194"},{"id":"00015346","register_sub_id":"101","register_pk":"532470","name":"井田家住宅主屋","kana":"いだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県芦屋市三条町154","lat":34.73529167,"lng":135.29527778,"geo_status":"db","era":"江戸末期／昭和4年・平成7年・令和5年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積150㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0838","desc":"三条八幡神社の北西、用水路沿いの敷地に建つ農家の主屋。通りに北面するつし二階建切妻造平入鉄板葺で桟瓦葺下屋を付す。西に旧土間、東に田の字形に部屋を並べ、南東に床を構えた座敷、南西にさらに座敷棟を延ばす。建ち低い主屋が農村集落の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015346"},{"id":"00015347","register_sub_id":"101","register_pk":"532471","name":"井田家住宅蔵","kana":"いだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市三条町154","lat":34.73532778,"lng":135.29519722,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積15㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0839","desc":"主屋北西に位置する家財蔵。２階建切妻造妻入桟瓦葺で外壁漆喰塗仕上で、軒に鉢巻を廻らし、腰に高く竪板を張る。南に戸口、北妻と東面に塗込の庇付き窓を開ける。内部は各階板敷の一室で小屋組は登梁形式の和小屋。小規模ながら用水路沿いの点景となる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015347"},{"id":"00004809","register_sub_id":"101","register_pk":"105799","name":"稲岡家住宅主屋","kana":"いなおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加西市三口町813-2","lat":34.86873852,"lng":134.83657713,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積170㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"28 － 0192","desc":"造り酒屋の事務所兼用住宅主屋。東西棟，入母屋造，桟瓦葺のつし２階建で，東方の土間部は棟を落としたつくりとし，南北東３面に下屋を廻す。つし２階に虫籠窓を開けた伝統的な外観とするが，床上部に１間幅の中廊下を配するなど近代的な要素を併せもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004809"},{"id":"00004810","register_sub_id":"101","register_pk":"105800","name":"稲岡家住宅離れ","kana":"いなおかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県加西市三口町813-2","lat":34.86872976,"lng":134.83641317,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"28 － 0193","desc":"主屋の西に接して東西棟で建つ。桁行６間半梁行３間，入母屋造，桟瓦葺の木造２階建で，８畳２室の四周に縁と廊下を廻す。背面東方の主屋との取り合い部には半切妻造，フランス瓦葺，外壁ドイツ壁で妻をハーフティンバー風に見せる１室洋館を配するのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004810"},{"id":"00014899","register_sub_id":"101","register_pk":"519159","name":"井上家住宅主屋","kana":"いのうえけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町福吉字前田233","lat":35.00854444,"lng":134.31676667,"geo_status":"db","era":"嘉永6年(1853)／昭和40年代改修","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造2階建、茅葺（鉄板仮葺）、建築面積267㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0813","desc":"福吉の三叉路の南西に位置する旧家の主屋。敷地中央に南面する寄棟造茅葺（鉄板仮葺）の東西棟で、南面西寄りに式台を構える。内部は東を梁組を現した土間、西に前後二列八室を配し、南北室境に廊下状の部屋を設ける。大型民家で地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014899"},{"id":"00014900","register_sub_id":"101","register_pk":"519160","name":"井上家住宅穀蔵","kana":"いのうえけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町福吉字前田233","lat":35.00863333,"lng":134.31684167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0814","desc":"主屋の北東、東寄りに位置する穀蔵。石積基礎に建つ二階建切妻造妻入の桟瓦葺。外壁は中塗仕上で、南面西寄りに戸口を設け、二階東面に１箇所窓を開ける。内部は各階１室の板敷。小屋は登梁形式。閉鎖的な外観で、一階内壁は縦板張とし丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014900"},{"id":"00014902","register_sub_id":"101","register_pk":"519162","name":"井上家住宅帳面蔵","kana":"いのうえけじゅうたくちょうめんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町福吉字前田233","lat":35.00868889,"lng":134.31669167,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積9.0㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0816","desc":"主屋の北方、敷地北西隅に位置する帳簿類を収納する蔵。平屋建切妻造妻入の桟瓦葺で石積基礎に建つ。外壁は軒まで塗込めた漆喰塗仕上とする。南面に鳥居形の戸口には、片開きの掛子塗戸を吊り、内部は一室の板敷で縦板張とする。無窓とし厳重なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014902"},{"id":"00014901","register_sub_id":"101","register_pk":"519161","name":"井上家住宅中蔵","kana":"いのうえけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町福吉字前田233","lat":35.00865278,"lng":134.31677778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0815","desc":"主屋の北、帳面蔵と穀蔵間に位置する家財蔵。石積基礎に建つ二階建切妻造妻入で、置屋根形式の桟瓦葺とする。外壁は漆喰塗仕上で腰と出隅を海鼠壁とする。内部は各階一室の板敷で南西に階段を配す。北妻地棟上に付す漆喰塗仕上の唐破風屋根が目を惹く土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014901"},{"id":"00014903","register_sub_id":"101","register_pk":"519163","name":"井上家住宅門","kana":"いのうえけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県佐用郡佐用町福吉字前田233","lat":35.00840833,"lng":134.31675556,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.1m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0817","desc":"敷地南面東寄りに建つ切妻造桟瓦葺の腕木門。主柱間を繋いだ楣上に束を立て、腕木で軒を支持、軒は一軒疎垂木。門口は東寄りを一間幅の潜戸付大戸、西寄りを半間幅引戸の脇口とする。東西端の南に屋根付袖壁を付した独特な構えで、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014903"},{"id":"00005012","register_sub_id":"101","register_pk":"106002","name":"今井家住宅主屋","kana":"いまいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷534-1","lat":35.16853387,"lng":134.7937558,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積269㎡","structure_material":"木造平屋一部2階建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0206","desc":"西面して建つ。街路側の南を入母屋造，北を切妻造とする南北棟の一部２階建で，西面に下屋を設ける。屋根は桟瓦葺，外壁は漆喰塗であるが，南面は押縁下見板張とする。内部は南を土間とし，北に田の字型で４室を構える。角地に建ち，町並景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005012"},{"id":"00005013","register_sub_id":"101","register_pk":"106003","name":"今井家住宅西塀","kana":"いまいけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷534-1","lat":35.16859983,"lng":134.79367213,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長8.2m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0207","desc":"主屋の正面北寄りに設けられたＬ字型の塀で，座敷の前庭を囲んでいる。折曲がり延長約９ｍの真壁造で，腰を縦板張で覆い，主屋側の端部に前庭への潜戸を設ける。柱に挿した腕木で桁を受け，桟瓦葺屋根を架ける。角地の街路景観を演出している構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005013"},{"id":"00006251","register_sub_id":"101","register_pk":"107235","name":"岩佐家住宅主屋","kana":"いわさけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県明石市鳥羽538","lat":34.667507,"lng":134.968063,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0274","desc":"敷地の中央西寄りに南面して建つ木造２階建。桁行６間，梁間３間の入母屋造，桟瓦葺で南，西，北に下屋が付く。内部は東に土間，西に口の間，座敷８畳，居間８畳，仏間３畳などを喰い違いに配す。外壁は黒漆喰の塗屋で，起りのある破風とともに重厚な外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006251"},{"id":"00006252","register_sub_id":"101","register_pk":"107236","name":"岩佐家住宅土蔵","kana":"いわさけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県明石市鳥羽538","lat":34.667446,"lng":134.968155,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0275","desc":"主屋の東に建つ土蔵造２階建，方２間規模の南北棟である。戸口は西面にあり，片引きの土戸，板戸，格子戸を建て込み，主屋との間に設けた納戸を蔵前としている。小屋組は地棟に登梁を架けている。外壁は白漆喰塗で，屋根は本瓦葺，切妻造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006252"},{"id":"00003891","register_sub_id":"101","register_pk":"104881","name":"上田家住宅主屋","kana":"うえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市犬飼152-1","lat":35.04530742,"lng":135.175232,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"28 － 0138","desc":"庄屋宅として建てられたもので，規模は桁行８間梁間５間，屋根は茅葺。平面は東に土間を設け，西側を床上部とし，西南隅は床棚書院を備える座敷とする他，南面中央に式台玄関を設ける。祈祷札及び形式から１８世紀中頃の建築と考えられる。茅葺民家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003891"},{"id":"00008518","register_sub_id":"101","register_pk":"134914","name":"上原家住宅米蔵","kana":"うえはらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市長洲本通3-60","lat":34.72346499,"lng":135.42853853,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0465","desc":"敷地西面中央に建ち、南側の門と接続する。桁行四・八メートル梁間二・八メートル、土蔵造二階建、切妻造本瓦葺で、東側に庇を付ける。外壁は漆喰塗で北・西面を竪板張とし、西面二階に小窓を穿つ。離れや門と一体で、庄屋屋敷の表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008518"},{"id":"00008514","register_sub_id":"101","register_pk":"134910","name":"上原家住宅主屋","kana":"うえはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市長洲本通3-60","lat":34.72349784,"lng":135.42866476,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0461","desc":"角地の敷地北面に建つ。桁行一四メートル梁間一〇メートル、木造平屋建、切妻造桟瓦葺で、正・背面を下屋とする。内部は西端が土間で、床上部は六間取とし、大黒柱を二本たてる。外壁を漆喰で塗り込めるなど重厚な外観で、庄屋の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008514"},{"id":"00008515","register_sub_id":"101","register_pk":"134911","name":"上原家住宅納屋","kana":"うえはらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市長洲本通3-60","lat":34.7234477,"lng":135.42879444,"geo_status":"db","era":"明治前期／明治後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0462","desc":"主屋東側に接続して建ち、桁行七・八メートル梁間六・九メートル、二階建、切妻造桟瓦葺である。1階は土間の納屋で、二階に座敷二室を配し、主屋から階段で出入する。背面の路地側は屋根を二重とし、壁は腰高の竪板張として主屋と統一的な外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008515"},{"id":"00008516","register_sub_id":"101","register_pk":"134912","name":"上原家住宅離れ","kana":"うえはらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市長洲本通3-60","lat":34.7233941,"lng":135.4284832,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0463","desc":"敷地南西隅に建ち、北側にある門に接する。桁行四・四メートル梁間四・七メートル、切妻造本瓦葺である。内部はトコと棚を備えた六畳で、北側に門の二階に通じる階段を設ける。外壁は竪板張で出格子窓を付け、軒を塗り込めるなど、格式ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008516"},{"id":"00008517","register_sub_id":"101","register_pk":"134913","name":"上原家住宅南蔵","kana":"うえはらけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市長洲本通3-60","lat":34.72331802,"lng":135.4287149,"geo_status":"db","era":"明治前期／昭和61年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積60㎡","structure_material":"土蔵造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0464","desc":"敷地東南隅に西面して建ち、桁行一一メートル梁間九・七メートル、土蔵造平屋建、切妻造本瓦葺である。外壁はモルタル塗で腰を海鼠壁とし、西側の出入口には、軍配風の模様を表現した漆喰塗の引戸をたてる。落ち着いた佇まいの庭空間に景趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008517"},{"id":"00008519","register_sub_id":"101","register_pk":"134915","name":"上原家住宅門","kana":"うえはらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市長洲本通3-60","lat":34.72343041,"lng":135.4285126,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口4.1m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0466","desc":"敷地西面、米蔵と離れの間に建つ。桁行四・一メートル梁間五・二メートル、二階建、切妻造本瓦葺である。門口二・三メートルに鏡柱をたてて、欅の板戸を吊り、両側に潜戸を開く。米蔵や離れとは棟高を違え、屋根を二段とし、重厚で変化ある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008519"},{"id":"00010012","register_sub_id":"101","register_pk":"196159","name":"魚橋家住宅内蔵","kana":"うおはしけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市伊伝居字馬場崎88","lat":34.84920482,"lng":134.70333117,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0577","desc":"離れ座敷の西後方に東西棟で建つ。土蔵造二階建、桁行五・九メートル梁間三・八メートル、切妻造本瓦葺で、東面の戸口に桟瓦葺の下屋を設ける。外壁漆喰塗で鉢巻を廻らし、東面の腰を海鼠壁として二階に窓を穿ち、他は竪板を張る。衣類などを保管した衣装蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010012"},{"id":"00010010","register_sub_id":"101","register_pk":"196157","name":"魚橋家住宅主屋","kana":"うおはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市威徳寺町24","lat":34.84905704,"lng":134.70361058,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積137㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0575","desc":"野里街道に東面する二階建町家。屋根はやや起らせた本瓦葺で下屋を桟瓦葺とする。一階正面は出格子や駒寄せを設け、出桁造の二階は黒漆喰塗とし、木瓜形の虫籠窓を並べる。通り土間沿いに居室を二列並べ、上手奥から座敷、仏間とする。野里の風格ある町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010010"},{"id":"00010013","register_sub_id":"101","register_pk":"196160","name":"魚橋家住宅外蔵","kana":"うおはしけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市伊伝居字馬場崎81-2","lat":34.8492109,"lng":134.70321315,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積92㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0578","desc":"敷地西奥に南北棟で建つ。土蔵造二階建、桁行一四・五メートル梁間五・一メートル、切妻造本瓦葺で、東面に桟瓦葺の下屋を設ける。外壁漆喰塗で鉢巻を廻らし、腰を竪板張とする。内部は南北に二分され、各々に戸口を設ける。日用具を収納した道具蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010013"},{"id":"00010011","register_sub_id":"101","register_pk":"196158","name":"魚橋家住宅離れ座敷","kana":"うおはしけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市威徳寺町24","lat":34.84915864,"lng":134.70345595,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0576","desc":"主屋後方に東西棟で建つ。入母屋造桟瓦葺で周囲に縁と下屋を廻らし、西端に便所を附属する。西奥の一〇畳主室と手前の次の間からなり、主室座敷飾の付書院や部屋廻りの欄間に、繊細な意匠の組子を入れた格狭間などを飾る。開放的で落ち着いた佇まいの離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010011"},{"id":"00013296","register_sub_id":"101","register_pk":"366285","name":"梅谷家住宅北塀及び西塀","kana":"うめたにけじゅうたきたべいおよびにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県加古郡播磨町宮北一丁目408-5","lat":34.71708333,"lng":134.86629722,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、総延長35m","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0740","desc":"敷地北面と西面を囲む塀で、北塀の中央付近に木戸を開く。半間おきに柱を立て腕木で桁を支え、屋根は桟瓦で葺く。外側は焼杉の竪板張で上部を真壁漆喰塗とし、内側は北塀が真壁漆喰塗、西塀が竪板張で、大谷石の支柱で支持する。宅地外周部の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013296"},{"id":"00013294","register_sub_id":"101","register_pk":"366283","name":"梅谷家住宅主屋","kana":"うめたにけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県加古郡播磨町宮北一丁目408-5","lat":34.71707222,"lng":134.86648611,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0738","desc":"喜瀬川右岸の小学校前に通学用の別宅として建てた。敷地北東に建つ木造平屋建で、寄棟造と入母屋造を組み合わせた屋根をかける。北東端に玄関を配し、南に書斎と居間を並べる。書斎は洋室で漆喰塗天井にシャンデリアを吊る。別宅の必要機能をまとめた住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013294"},{"id":"00013295","register_sub_id":"101","register_pk":"366284","name":"梅谷家住宅離れ","kana":"うめたにけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県加古郡播磨町宮北一丁目408-5","lat":34.71703056,"lng":134.86636389,"geo_status":"db","era":"昭和14年頃／昭和40年代改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0739","desc":"主屋の西側に建つ木造二階建、入母屋造桟瓦葺で、外壁を焼杉の竪板張とする。一階は床、棚、付書院を備えた八畳の主座敷と六畳の座敷の南に広縁を付し、北に茶室を配す。二階は座敷が三室で南に縁を付す。良材を駆使した上質な離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013295"},{"id":"00006274","register_sub_id":"101","register_pk":"107258","name":"浦家住宅主屋","kana":"うらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市南郷町22-3","lat":34.74642263,"lng":135.33145331,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積131㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0276","desc":"吉阪隆正の初期ＲＣ造住宅作品。東西に並べた二つの正方形ブロックと中間の玄関部からなる。各ブロックは床と屋根のスラブを各辺中央のく字形柱で支えてピロティとし，煉瓦外壁に突出する小口が表情を与える。各所に現した原色が鮮やかなモダニズム住宅の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006274"},{"id":"00000998","register_sub_id":"101","register_pk":"101988","name":"うろこの家（旧ハリヤー邸）主屋","kana":"うろこのいえ（きゅうはりやーてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市中央区北野町2-20-4","lat":34.70293988,"lng":135.19068708,"geo_status":"db","era":"明治末期／大正年間移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造２階建，瓦葺，建築面積135㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0038","desc":"北野山本地区を代表する異人館のひとつで，伝建地区の外延，六甲山麓の山際の高いところに位置する。外壁に貼りまわされた天然スレートが鱗状にみえることから「うろこの家」の愛称があり，円形の展望塔とあいまって観光客の人気を集めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000998"},{"id":"00003467","register_sub_id":"101","register_pk":"104457","name":"榎本家（旧小川家）住宅主屋","kana":"えのもとけ（きゅうおがわけ）じゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県洲本市五色町鮎原上944","lat":34.40477072,"lng":134.83713824,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"28 － 0124","desc":"近世より近隣に重きをなし，近代に入って旧鮎原村の村長も務めた旧家の住宅。伝承より明治元年には既に当地にあったことが知られる。入母屋造，本瓦葺で，正側面三方に下屋をかける。内部はやや改造されているが，食違い六間取りを基本とする平面形態である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003467"},{"id":"00003469","register_sub_id":"101","register_pk":"104459","name":"榎本家（旧小川家）住宅長屋門","kana":"えのもとけ（きゅうおがわけ）じゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県洲本市五色町鮎原上944","lat":34.40459645,"lng":134.83711993,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"28 － 0126","desc":"敷地の南辺を画する長屋門。本瓦葺，入母屋造で，門の西側に供部屋，東側に作業場２室を設ける。やや建ちを高く取り，上部小壁の一部を開放とする。旧家の格を示すとともに，近世から近代にかけての淡路島の農村集落景観を今日に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003469"},{"id":"00003468","register_sub_id":"101","register_pk":"104458","name":"榎本家（旧小川家）住宅離れ","kana":"えのもとけ（きゅうおがわけ）じゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県洲本市五色町鮎原上944","lat":34.40487217,"lng":134.83702086,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造及び木造平屋一部2階建、瓦葺、建築面積140㎡","structure_material":"土蔵造及び木造平屋一部2階建","registered":"2003.07.01(平成15.07.01)","register_no":"28 － 0125","desc":"主屋の背面側に建つ。置屋根形式の土蔵と居室部が接続されているが，土蔵が先に建ち，後に居室部を増築したと思われる。居室部には９畳，６畳座敷と８畳１室を設け，南側を廊下で繋ぐ。土蔵には２階を設ける。大規模民家の敷地景観を今日に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003468"},{"id":"00008525","register_sub_id":"101","register_pk":"134921","name":"大石家住宅内蔵","kana":"おおいしけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46463003,"lng":134.92993171,"geo_status":"db","era":"昭和前期／平成18年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積46㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0472","desc":"主屋と裏ノ部屋との間に南北棟で建つ。切妻造桟瓦葺で、東面の下屋が裏ノ部屋への廊下となり、主屋との間には半間幅の渡り廊下を設ける。桁行六・六メートル梁間四・三メートルの二階建土蔵、北側に納戸を付設。乱積基礎上、漆喰仕上げとする標準的な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008525"},{"id":"00008522","register_sub_id":"101","register_pk":"134918","name":"大石家住宅裏ノ部屋","kana":"おおいしけじゅうたくうらのへや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46469894,"lng":134.93004394,"geo_status":"db","era":"昭和前期／平成18年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0469","desc":"主屋の北方、敷地北辺に東西棟で建つ。桁行一二メートル梁間五・四メートルの木造二階建、切妻造桟瓦葺。一、二階とも東寄りに六畳を東西に二室並べ、南北に切目縁を付し、東室にトコを設け、主室とする。一階は根太天井、二階は棹縁天井。機能的な居住施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008522"},{"id":"00008523","register_sub_id":"101","register_pk":"134919","name":"大石家住宅木小屋及び奥内庭","kana":"おおいしけじゅうたくきごやおよびおくうちにわ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46456702,"lng":134.92976828,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部平屋建、瓦葺、建築面積51㎡","structure_material":"木造2階一部平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0470","desc":"主屋西方に南北棟の切妻造桟瓦葺、木造二階建の木小屋が建つ。主屋との間を両下造平屋建の奥内庭が繋ぎ、その軒が木小屋正面にまわり、庇となる。南正面は木小屋が中塗仕上げの真壁とし、柱や貫を見せ、奥内庭は格子窓を大きく開け、変化のある正面構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008523"},{"id":"00008526","register_sub_id":"101","register_pk":"134922","name":"大石家住宅北蔵","kana":"おおいしけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46473242,"lng":134.92982735,"geo_status":"db","era":"明治25年／昭和前期改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積86㎡","structure_material":"土蔵造平屋一部2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0473","desc":"敷地北辺、裏ノ部屋の西に続く。東西棟の切妻造桟瓦葺の置屋根とする。桁行一四メートル梁間四・三メートルの二階建土蔵。東端に味噌蔵、西寄りに東西二室からなる道具蔵、その間に通路を設ける。南面には二階建の蔵前を付設。腰板張で、漆喰仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008526"},{"id":"00008527","register_sub_id":"101","register_pk":"134923","name":"大石家住宅米蔵","kana":"おおいしけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.4647462,"lng":134.9297289,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積56㎡","structure_material":"土蔵造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0474","desc":"道具蔵の西に東西棟で建つ。桁行七・八メートル梁間五・六メートル、北蔵より棟を高くするが、二階床を張らず平屋建土蔵。切妻造桟瓦葺の置屋根。北蔵と同じ仕様で外壁を仕上げ、規則的に窓を穿ち、敷地北辺にリズム感のある構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008527"},{"id":"00008530","register_sub_id":"101","register_pk":"134926","name":"大石家住宅集水槽","kana":"おおいしけじゅうたくしゅうすいそう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46463003,"lng":134.92986673,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、面積1.9㎡","structure_material":"煉瓦造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0477","desc":"主屋の北、内蔵の西に位置する。内法幅一・四メートル奥行〇・九三メートル、深さ〇・八メートルのコンクリート造の水槽の上部に、幅、奥行とも一・四メートル、高さ二・三メートル、下部にアーチを穿つ煉瓦造集水槽を設ける。近代的な自家用水道の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008530"},{"id":"00008520","register_sub_id":"101","register_pk":"134916","name":"大石家住宅主屋","kana":"おおいしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46448038,"lng":134.92998094,"geo_status":"db","era":"明治8年頃／明治中期増築・昭和60年・平成21年改修","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、茅葺（スレート仮葺）、建築面積279㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0467","desc":"出石川沿いの道の北側に占める敷地中央に、南面して建つ。正面二〇メートル奥行一二メートル、入母屋造茅葺とし、東面に二階屋を張り出す。西寄りに土間を設け、東側の床上には、座敷飾りを構える奥ノ間やチョウダイなどを配する。大規模な農家建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008520"},{"id":"00008531","register_sub_id":"101","register_pk":"134927","name":"大石家住宅中門","kana":"おおいしけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46442525,"lng":134.92993368,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口1.4m、塀付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0478","desc":"主屋座敷南の庭を区切る塀が、式台玄関横から南へ延び、その中間に中門が位置する。薬医門で、切妻造桟瓦葺。切石礎石上に、方柱を間口一・四メートルにたて、冠木を架す。軒は一軒疎垂木。背面には控柱をたて、男梁や貫で繋ぐ。簡素で軽快な庭門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008531"},{"id":"00008535","register_sub_id":"101","register_pk":"134931","name":"大石家住宅東北築地塀","kana":"おおいしけじゅうたくとうほくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46471506,"lng":134.93013087,"geo_status":"db","era":"昭和前期／昭和60年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、延長16m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0482","desc":"敷地東北隅、東蔵北方から裏ノ部屋に至る折れ曲がり延長一六メートルの土塀で、東蔵に接して間口一・九メートルの腕木門を付ける。腰高に野石を積み上げて基礎とし、上部を土塀、漆喰仕上げとする。桟瓦葺。東から北背面にかけての屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008535"},{"id":"00008529","register_sub_id":"101","register_pk":"134925","name":"大石家住宅飯米蔵及び水車小屋","kana":"おおいしけじゅうたくはんまいぐらおよびすいしゃごや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46462215,"lng":134.92977025,"geo_status":"db","era":"明治17年／昭和前期改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造及び木造2階一部平屋建、瓦葺、建築面積30㎡、塀付","structure_material":"土蔵造及び木造2階一部平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0476","desc":"籾蔵の東南に位置する。桁行五・一メートル梁間四・一メートルの二階建土蔵。南北棟の切妻造桟瓦葺の置屋根。乱積基礎上に切石を二段載せ、腰竪板張の漆喰仕上げとする。東面に庇を付け、北隅を間仕切り、水車を設けた。近代の生活の有り様が偲ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008529"},{"id":"00008524","register_sub_id":"101","register_pk":"134920","name":"大石家住宅東蔵","kana":"おおいしけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46460246,"lng":134.93012073,"geo_status":"db","era":"明治12年／明治中期増築・明治44年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0471","desc":"主屋の東北、敷地の東辺に位置する。南北棟の切妻造桟瓦葺で、南半部の棟を下げ、西面に下屋を付け蔵前とする。桁行八・四メートル梁間四・九メートル、土蔵造二階建。南北の二室に分かれ、北室一階は壁板張とする。敷地東辺の景観を構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008524"},{"id":"00008534","register_sub_id":"101","register_pk":"134930","name":"大石家住宅東塀","kana":"おおいしけじゅうたくひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46439178,"lng":134.93012073,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長5.0m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0481","desc":"敷地東辺の南寄りに位置し、南築地塀に矩折れに取り付く。延長五・〇メートルで、腰竪板張、上部漆喰仕上げとし、中央に引戸をたてる。腕木を出して、軒桁を支持する。切妻造桟瓦葺として、北側一・二メートルを一段高くする。南築地と対照的な軽快な塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008534"},{"id":"00008521","register_sub_id":"101","register_pk":"134917","name":"大石家住宅東部屋","kana":"おおいしけじゅうたくひがしべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.464441,"lng":134.93010892,"geo_status":"db","era":"大正8年／平成21年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0468","desc":"主屋の東、敷地東辺に南北棟で建つ。緩い起りの切妻造桟瓦葺で、南・西面に下屋庇をまわす。南北に二室を配し、榑縁を巡らす。南室にトコとトコ脇、付書院、北室に一間半の違棚を構え、室境に彫刻欄間を飾る。軸部や天井を漆塗とし、質の高い座敷空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008521"},{"id":"00008533","register_sub_id":"101","register_pk":"134929","name":"大石家住宅南築地塀","kana":"おおいしけじゅうたくみなみついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46439572,"lng":134.929723,"geo_status":"db","era":"昭和前期／昭和60年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、延長48m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0480","desc":"敷地南面、通りに沿って東西に延びる土塀。西寄りに間口二・七メートルの門口を設け、矩折れに北にまわり込む。総延長四八メートル。野石を乱積とした腰高の基礎上、土塀とし、表面をモルタル仕上げ、上部に桟瓦を葺く。重厚な表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008533"},{"id":"00008528","register_sub_id":"101","register_pk":"134924","name":"大石家住宅籾蔵","kana":"おおいしけじゅうたくもみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46468713,"lng":134.92971512,"geo_status":"db","era":"明治19年／昭和前期改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0475","desc":"米蔵の南に南北棟で建つ。桁行五・六メートル梁間四・一メートルの二階建土蔵。東正面には二階建の蔵前が矩折れに続く。切妻造桟瓦葺で、蔵前は葺き下ろす。乱積基礎、腰下見板張とする漆喰仕上げ。妻を見せる米蔵と並び立ち変化のある外構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008528"},{"id":"00008532","register_sub_id":"101","register_pk":"134928","name":"大石家住宅籾蔵東門","kana":"おおいしけじゅうたくもみぐらひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市但東町矢根字金屋1076他","lat":35.46467728,"lng":134.92975253,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口1.3m、塀付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0479","desc":"籾蔵南面柱筋から東に延び、飯米蔵塀に付く。延長四・〇メートルで、中央間一・三メートルを穿ち、引戸をたてる。東寄り二間は腕木を出し、切妻造桟瓦葺屋根を架ける。南面は野石を乱積。塀は腰モルタル、上部漆喰仕上げとし、籾蔵と一連の景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008532"},{"id":"00009810","register_sub_id":"101","register_pk":"195639","name":"大崎家住宅主屋","kana":"おおさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県高砂市高砂町字藍屋町1667","lat":34.74764914,"lng":134.80558671,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0568","desc":"大通りに北面する二階建町家。東寄りの通り土間を後方にのばし、中庭を囲むように台所浴室棟や便所棟などを配する。主体部は通り土間沿いに三室を並べる。正面に出格子をたて、二階軒は出桁造で、両側に袖うだつをあげる。高砂の近代町家の一典型を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009810"},{"id":"00001449","register_sub_id":"101","register_pk":"102439","name":"大歳家住宅隠居部屋","kana":"おおとしけじゅうたくいんきょべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72974566,"lng":134.84223121,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0064","desc":"主屋の東方，離屋の南東方に位置し，敷地北東辺の外塀に沿って建ち，南東方で納屋に連なる。桁行４間半，梁間２間半の本瓦葺の身舎の前面に半間幅の庇を出し，縁付きの６畳間の南東に４畳の前室と，納屋との間に１間通りの土間入口を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001449"},{"id":"00001454","register_sub_id":"101","register_pk":"102444","name":"大歳家住宅穀物蔵","kana":"おおとしけじゅうたくこくもつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72927566,"lng":134.8419888,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0069","desc":"屋敷地の南端，屋敷地の南東辺と南西面とが交わる入隅部に建つ桟瓦葺，切妻屋根，平入の穀物蔵で，北東方に接続する大工部屋と屋根を一体的につくる。桁行３間半，梁間２間の規模で，街路側の外観は漆喰塗の軒回り以外を縦板貼とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001454"},{"id":"00001455","register_sub_id":"101","register_pk":"102445","name":"大歳家住宅米蔵","kana":"おおとしけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72938824,"lng":134.84197517,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0070","desc":"主屋の南方，南庭の中央でやや穀物蔵寄りに建つ。桁行５間，梁間２間半，桟瓦葺，切妻屋根，平入の比較的規模の大きな蔵で，入口両脇の腰を海鼠壁とする。棟の軸が，この棟だけ微妙にずれていることから，主屋より古い可能性がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001455"},{"id":"00001447","register_sub_id":"101","register_pk":"102437","name":"大歳家住宅主屋","kana":"おおとしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.729622,"lng":134.8420901,"geo_status":"db","era":"天保6","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積455㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0062","desc":"加古川下流沿岸地域を差配した大庄屋の屋敷で，新野辺村の中央部に位置する。本瓦葺，入母屋造，つし２階の主屋は，土間玄関と８室を主体部とし，南と北西に張出部を設ける。建物規模とともに，上段の間の意匠などに大庄屋の格式と風格をみることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001447"},{"id":"00001451","register_sub_id":"101","register_pk":"102441","name":"大歳家住宅茶室","kana":"おおとしけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72962348,"lng":134.841934,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0066","desc":"主屋の南方，主屋座敷縁側の地先に位置する。３畳の茶室，２畳の水屋から成る。桟瓦葺，切妻屋根で，茶室の南側に銅板葺の土庇を差し掛ける。大庄屋の生活様態の一端を窺い知ることのできる接客施設として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001451"},{"id":"00001450","register_sub_id":"101","register_pk":"102440","name":"大歳家住宅長屋・長屋門","kana":"おおとしけじゅうたくながや・ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.729324,"lng":134.842056,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積284㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0065","desc":"約９００坪の敷地の南東辺に沿って建ち，南東辺のほぼ中央に門を開く。門の北方に蔵風の建屋，南方に門と一体となった便益棟が続き，さらに南に大工部屋が連なる。北方の建屋は腰上部を白壁として板貼壁が続く街路沿いの景観にアクセントをつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001450"},{"id":"00001452","register_sub_id":"101","register_pk":"102442","name":"大歳家住宅西什器蔵","kana":"おおとしけじゅうたくにしじゅうきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72981286,"lng":134.84209104,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0067","desc":"屋敷地の北端部，離屋の北西方に位置し，屋敷地北西辺の外塀に沿って建つ。桁行３間，梁間１間半の規模を有する瓦葺，切妻屋根，妻入の閉鎖的な土蔵で，屋敷構えの一構成要素になる。北側の土蔵とともに什器を納める蔵とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001452"},{"id":"00001448","register_sub_id":"101","register_pk":"102438","name":"大歳家住宅離屋","kana":"おおとしけじゅうたくはなれや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72977338,"lng":134.84213128,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0063","desc":"主屋の北西方に位置し，東西の什器蔵・隠居部屋とともに屋敷地の北端部の裏庭的空間を形成する一要素となる。桟瓦葺，入母屋造，簓子下見の２階建建屋で，階下は３畳間・浴室・便所と入口部の板敷間から成り，主屋のオクナンドの北側廊下に接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001448"},{"id":"00001453","register_sub_id":"101","register_pk":"102443","name":"大歳家住宅東什器蔵","kana":"おおとしけじゅうたくひがしじゅうきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市別府町新野辺881","lat":34.72982721,"lng":134.84216228,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0068","desc":"屋敷地の東北辺と西北辺が交わる入隅部に建ち，離屋・隠居部屋とともに裏庭的空間の一画をつくる。桁行３間，梁間２間の瓦葺，切妻屋根の閉鎖的な造りの土蔵で，東南妻面に庇を差し掛けて入口を設ける。西方の土蔵と同様に什器類を納める蔵とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001453"},{"id":"00006018","register_sub_id":"101","register_pk":"107003","name":"小河家住宅裏門","kana":"おがわけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.795425,"lng":134.982895,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口1.3m、塀延長13.8m付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0261","desc":"敷地南辺の西端に位置し，柱間１．３ｍの腕木門の形式をとり，木造，切妻造，桟瓦葺とする。中央に両開板戸を吊り，上部に縦格子の欄間を付ける。両袖壁西方及び東方に塀を続け，北方に延ばし，主屋土間の南面に繋げる。小規模ながら，上質な意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006018"},{"id":"00006005","register_sub_id":"101","register_pk":"106990","name":"小河家住宅表門","kana":"おがわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79594388,"lng":134.98310463,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、間口2.5m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0259","desc":"敷地北側に位置し，北辺よりやや南側に建つ。塀重門の形式をとり，中央間に幅３２ｃｍ，高さ２．８ｍの木柱を立て，木製両開戸を吊り，銅製パイプのランタン吊を渡す。西袖に潜戸を設ける。広大な敷地の表構えを構成し，屋敷正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006005"},{"id":"00006002","register_sub_id":"101","register_pk":"106987","name":"小河家住宅主屋","kana":"おがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79556455,"lng":134.98300871,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積284㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0253","desc":"南北に長い敷地の中央やや南側に位置し，表門から離れて北面して建つ。間口１１間，奥行９間の規模で，木造平屋建，入母屋造，桟瓦葺とする。正面に式台玄関を構え，東端に１０畳客座敷を設け，南側に６畳上段の間を張り出す。材料，意匠，技術ともに優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006002"},{"id":"00006016","register_sub_id":"101","register_pk":"107001","name":"小河家住宅女中部屋","kana":"おがわけじゅうたくじょちゅうべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79572921,"lng":134.98295794,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0258","desc":"敷地西辺に沿って，主屋と納戸の間に建つ。桁行３間，梁間２間で，木造平屋建，寄棟造，桟瓦葺とする。７畳半間の西側に廊下を設け，南側に浴室，北側に便所を付ける。更衣室は主屋台所に連絡する。 外壁を縦板張とし，上部を漆喰塗とする。庭に面し，質素なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006016"},{"id":"00006017","register_sub_id":"101","register_pk":"107002","name":"小河家住宅外塀","kana":"おがわけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79559413,"lng":134.98318207,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長129m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0260","desc":"表門東袖から北の敷地境に延び，東に折れ，敷地北辺の東端及び東辺，南辺を廻り，裏門まで延びる。延長１２９ｍの木造桟瓦葺の塀。石垣の上に柱を半間毎に立て，腰を縦板張とする。要所に縦格子の高窓を設ける。敷地の東半部を囲い，上質な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006017"},{"id":"00006004","register_sub_id":"101","register_pk":"106989","name":"小河家住宅土蔵","kana":"おがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.795429,"lng":134.983063,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0255","desc":"主屋南側東寄りに建ち，桁行３間半，梁間２間半で，土蔵造２階建，切妻造，本瓦葺とする。西面に戸口を開き，主屋及び離れと廊下で結ばれ内蔵の性格をもつ。小屋は太い登梁等を使う。両妻壁に窓を開き，鉢巻を黒漆喰塗とし，壁面を縦板張とするなど上質なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006004"},{"id":"00006007","register_sub_id":"101","register_pk":"106992","name":"小河家住宅納戸","kana":"おがわけじゅうたくなんど","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79583439,"lng":134.98296906,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0257","desc":"敷地西辺に沿って，番人小屋の南側に建つ。桁行９間，梁間１間半で，内部を４室に区切り，土間の倉庫及び物置とする。西面は鉄板張とし，東面に出入口を設ける。腰を縦板張とし，上部を鼠漆喰塗及び中塗仕上げとして，格子窓を開く。庭に面し，質素なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006007"},{"id":"00006020","register_sub_id":"101","register_pk":"107005","name":"小河家住宅庭塀","kana":"おがわけじゅうたくにわべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79536445,"lng":134.98300885,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長7.7m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0263","desc":"土蔵南面西端から敷地南側の塀までを繋ぎ，離れ南側の庭の東辺を形成する。延長７．７ｍの規模で，木造，桟瓦葺屋根とする。半間毎に柱を立て，縦格子の窓を開き，上方を鼠漆喰仕上げとするなど，敷地外周の壁と同形式。庭の落ち着いた景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006020"},{"id":"00006019","register_sub_id":"101","register_pk":"107004","name":"小河家住宅庭門","kana":"おがわけじゅうたくにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79569314,"lng":134.98306055,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、杉皮葺、間口1.2m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0262","desc":"主屋北側の庭に面して建ち，生垣と共に，主屋式台玄関前と庭を区画する。柱間１．２ｍで，切妻造，杉皮葺とする。丸太柱を石造の添柱で補強し，桁等を竹材で造る。門扉は両開きの竹簀戸とし，上方を菱に組む。庭の景観に調和し，上質な外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006019"},{"id":"00006003","register_sub_id":"101","register_pk":"106988","name":"小河家住宅離れ","kana":"おがわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.795464,"lng":134.982971,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積67㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0254","desc":"中庭を挟んで主屋の南側に建ち，桁行６間，梁間３間の規模で，木造２階建，寄棟造，桟瓦葺とする。１階，２階共に書院付の８畳座敷と６畳の続き間を設け，南北に広縁を付ける。東端に納戸を付属する。全体を数寄屋風にまとめ，材料，意匠，技術共に秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006003"},{"id":"00006006","register_sub_id":"101","register_pk":"106991","name":"小河家住宅番人小屋","kana":"おがわけじゅうたくばんにんごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町3-6-24","lat":34.79596957,"lng":134.98299957,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0256","desc":"敷地北辺の表門の西側に建つ。桁行４間，梁間２間半の規模で，木造平屋建，寄棟造，桟瓦葺。７畳の座敷及び４畳半を並べ，南西隅に台所を突出させ，南東外に便所を設ける。切石積の石垣の上に建ち，北側は漆喰塗の壁に腰を縦板張とし，物見の出格子窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006006"},{"id":"00011771","register_sub_id":"101","register_pk":"210787","name":"長田家住宅（旧石阪家住宅）主屋","kana":"おさだけじゅうたく（きゅういしさかけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市兵庫区会下山町一丁目4-1","lat":34.679192,"lng":135.160173,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積121㎡","structure_material":"木造2階一部平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28 - 0658","desc":"南斜面の丘陵地に建ち、東半を二階建、西半を平屋建とする。西側の和室は網代天井や下地窓等数奇屋風意匠を見せる。東側にはポーチ付の玄関と吹抜けのある応接室、二階に洋室などを備える。手斧仕上げの付柱や梁を現しとした民芸調意匠の内部空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011771"},{"id":"00007900","register_sub_id":"101","register_pk":"108880","name":"梶原家住宅内大蔵","kana":"かじわらけじゅうたくうちおおくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77887556,"lng":134.75938227,"geo_status":"db","era":"江戸末期／大正期増築・昭和22頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積82㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0423","desc":"南離座敷の南東に位置する。南北棟の切妻造本瓦葺。桁行１２ｍ梁間５．７ｍ、土蔵造２階建。白漆喰仕上げで、西面の渡廊下側に戸口を設け、腰を海鼠壁とする。１、２階とも南北二室に分かれ、２階北室は幅広の板を敷く。窓庇持送りなど丁寧な仕事が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007900"},{"id":"00007902","register_sub_id":"101","register_pk":"108882","name":"梶原家住宅内蔵","kana":"かじわらけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77885181,"lng":134.75929757,"geo_status":"db","era":"江戸末期／昭和22頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0425","desc":"現像室の南方に位置する。東西棟の切妻造本瓦葺。桁行４．９ｍ梁間３．９ｍ、土蔵造２階建。外壁は白漆喰仕上げで、中庭に面する北・西面を腰海鼠壁とする。北面に出入口を設け、銅板葺庇をかける。２階西面窓庇の持送りには鏝細工を施す。中庭の一構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007902"},{"id":"00007898","register_sub_id":"101","register_pk":"108878","name":"梶原家住宅内腰掛待合","kana":"かじわらけじゅうたくうちこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77904083,"lng":134.75957027,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺、建築面積8.7㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0421","desc":"茶室しづの舎の北方に位置する。桁行３．２ｍ梁間２．０ｍ、屋根招造檜皮葺の腰掛。中柱に流木風の朽木を建て、大きく円形に欠き取る土壁で間仕切り、畳敷の貴人用とする。床は磚四半敷。北側に落棟で砂雪隠を設ける。簡潔ながら、精緻にデザインされた待合。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007898"},{"id":"00007910","register_sub_id":"101","register_pk":"108890","name":"梶原家住宅表門","kana":"かじわらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77934189,"lng":134.75932245,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、間口2.2m、左右袖塀付","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0433","desc":"敷地北辺、通りから入った位置に北面して建つ一間棟門。緩い起りのある切妻造桟瓦葺で、一軒疎垂木。五平柱を楣で固め、両開板戸を吊る。両側の袖塀は、腰板張の土壁仕上げ、桟瓦葺とし、西側には潜りを開ける。落ち着きのある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007910"},{"id":"00007909","register_sub_id":"101","register_pk":"108889","name":"梶原家住宅管理人部屋","kana":"かじわらけじゅうたくかんりにんべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77937745,"lng":134.75926705,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0432","desc":"敷地北辺、隅蔵と表門の間に位置する。東西棟の切妻造桟瓦葺、台形平面で、変形五畳に押入を付ける。内部は畳敷。棟高を抑え、内部は舟底状の天井を張る。東側に南北棟、切妻造桟瓦葺の便所を付設。屋敷構えを構成する建物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007909"},{"id":"00007892","register_sub_id":"101","register_pk":"108872","name":"梶原家住宅北離座敷","kana":"かじわらけじゅうたくきたはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77928667,"lng":134.75935335,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0415","desc":"主屋北側に廊下を介して南北に、式台玄関、二畳、水屋、八畳が続く。木造平屋建、桟瓦葺。八畳は太い槇の床柱を建て、円窓を開けるトコや平書院を構える座敷。式台玄関は西面に引分け戸をたて、大和葺の庇をかけ、土壁仕上げ。穏やかで気品ある佇まいになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007892"},{"id":"00007901","register_sub_id":"101","register_pk":"108881","name":"梶原家住宅現像室","kana":"かじわらけじゅうたくげんぞうしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77890449,"lng":134.75933682,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0424","desc":"内大蔵の西、渡廊下を挟んで建つ。桁行２．３ｍ梁間１．５ｍ、木造平屋建、桟瓦葺の招造屋根とする。渡廊下側に出入口、南・西面に小さな窓を開け、内部は現像のために黒く塗る。外部は中庭に面し、面皮柱を建て、聚楽の真壁造とするなど、凝った造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007901"},{"id":"00007903","register_sub_id":"101","register_pk":"108883","name":"梶原家住宅古書倉","kana":"かじわらけじゅうたくこしょぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77882185,"lng":134.75936368,"geo_status":"db","era":"昭和22頃","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積24㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0426","desc":"内大蔵の南、内蔵の東に位置する。東西棟の切妻造桟瓦葺。東西７．０ｍ南北２．９ｍの細長い鉄筋コンクリート造平屋建。外壁はモルタル掻き落とし仕上げで、西面に出入口、東面に窓を開ける。内部はコンクリート床に簀を敷き、壁板張とする。堅牢で実用的な書庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007903"},{"id":"00007904","register_sub_id":"101","register_pk":"108884","name":"梶原家住宅米蔵","kana":"かじわらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77930423,"lng":134.75919669,"geo_status":"db","era":"明治後期／昭和25改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0427","desc":"主屋の西北に南北棟で建つ。桁行１２ｍ梁間３．９ｍ規模の土蔵造２階建で、南半部は事務室に改修。屋根は切妻造本瓦葺で、北寄りの出入口には本瓦葺庇を付ける。高く竪板を張り、上部を白漆喰仕上げとする。北離座敷と相対する位置で、前庭空間を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007904"},{"id":"00007894","register_sub_id":"101","register_pk":"108874","name":"梶原家住宅下腹雪隠","kana":"かじわらけじゅうたくしたばらせっちん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77919887,"lng":134.75961468,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0417","desc":"茶室の東北に位置する。実用に供された雪隠。桁行１．７ｍ梁間１．３ｍ、木造平屋建、西面寄棟造東面切妻造、檜皮葺。西半部を小便所、東を大便所とし、西面に板戸、南面西半部に猿戸を吊る。壁は錆壁で、柱に丸太材を使う。緩やかな屋根と錆壁が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007894"},{"id":"00007891","register_sub_id":"101","register_pk":"108871","name":"梶原家住宅主屋","kana":"かじわらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.7791214,"lng":134.75933682,"geo_status":"db","era":"嘉永6／明治39増築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積435㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0414","desc":"通りの南側に占める敷地の中央に位置する。嘉永に建築された入母屋造本瓦葺、木造つし２階建の東に、明治期の切妻造平屋建の新座敷を付設。西寄りの土間、その東の六間取を基本に、新座敷には茶室や十五畳など良質な座敷を配する。大規模な住宅建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007891"},{"id":"00007773","register_sub_id":"101","register_pk":"108754","name":"梶原家住宅主屋","kana":"かじわらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字天神117-2","lat":34.78120742,"lng":134.75811359,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積302㎡","structure_material":"木造平屋一部2階建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0399","desc":"敷地中央に建つ。桁行１７ｍ梁間１３ｍ、木造つし２階建、入母屋造妻入瓦葺に、玄関や２階屋、台所等を付ける。東妻側に土間を配し、北面の庭側に玄関から続く座敷などの接客空間をもつ。多くの屋根を複雑に付設し、外壁を塗り込めるなど、風格ある外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007773"},{"id":"00007905","register_sub_id":"101","register_pk":"108885","name":"梶原家住宅隅蔵","kana":"かじわらけじゅうたくすみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.7793887,"lng":134.75922423,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0428","desc":"敷地の西北隅に位置する。南北棟の切妻造本瓦葺とする土蔵造２階建。敷地形状にあわせた台形平面で、桁行長辺４．２ｍ梁間３．９ｍの規模。外壁は高く竪板を張り、上部白漆喰仕上げとする。米蔵側の南面に出入口と窓を開ける。屋敷地西北隅の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007905"},{"id":"00007908","register_sub_id":"101","register_pk":"108888","name":"梶原家住宅外便所","kana":"かじわらけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77910144,"lng":134.75908303,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0431","desc":"主屋裏口脇に南北棟で建つ。桁行３．５ｍ梁間０．９７ｍの木造平屋建、切妻造桟瓦葺。南北四室に間仕切り、中央二室を大便所、北端を小便所とする。腰部をモルタル塗とする土壁で、中央二間に下地窓を開け、北面には猿戸を吊る。外作業用便所の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007908"},{"id":"00007906","register_sub_id":"101","register_pk":"108886","name":"梶原家住宅大工倉","kana":"かじわらけじゅうたくだいくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77870944,"lng":134.75939889,"geo_status":"db","era":"明治中期／昭和31頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積170㎡、貯水槽付","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0429","desc":"敷地の南辺に位置する。梁間９．１ｍ、桁行東面１６ｍ西面１３ｍの台形平面になる木造２階建。切妻造本瓦葺で、西面に奥行３．０ｍの下屋庇を付ける。外壁は全面竪板張で、西面北寄りと南面中央に出入口を開ける。敷地南に広がっていた塩田の名残を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007906"},{"id":"00007893","register_sub_id":"101","register_pk":"108873","name":"梶原家住宅茶室","kana":"かじわらけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77914929,"lng":134.75955167,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0416","desc":"主屋東北に位置する。茶室を中心に北に玄関、東に待合、南に三畳の水屋を付設し、廊下を介して主屋へ続く。待合は杉皮野地に竹垂木、錆壁。茶室は四畳半規模で、北に台目トコと貴人口を配し、西に大きく円窓、東に躙口を開ける。簡明直截な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007893"},{"id":"00007897","register_sub_id":"101","register_pk":"108877","name":"梶原家住宅茶室しづの舎","kana":"かじわらけじゅうたくちゃしつしづのや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77895613,"lng":134.7594773,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、茅葺一部瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0420","desc":"南離座敷の東に渡廊下を介して続く。四畳半と四畳、二畳中板の三席から構成される。北半部を落棟とする南北棟の入母屋造茅葺と、その西に付く切妻造桟瓦葺からなる。四畳席に杓の柄窓を穿つほか、様々な趣向が所々に見られ、意匠的に洗練された優麗な茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007897"},{"id":"00007899","register_sub_id":"101","register_pk":"108879","name":"梶原家住宅中門","kana":"かじわらけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77905323,"lng":134.75953308,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺、間口1.2m","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0422","desc":"内腰掛待合の砂雪隠と主屋との間に東西棟で建つ。間口１．２ｍの腕木門。高い礎石上に柱を建て、楣で固め、棟木を支持。材は杉丸太。一軒で疎らに竹と丸太の垂木を交互に配る。切妻造檜皮葺、棟は熨斗瓦２枚と雁振瓦。扉は両開の唐戸。軽快な意匠の中門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007899"},{"id":"00007774","register_sub_id":"101","register_pk":"108755","name":"梶原家住宅土蔵","kana":"かじわらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市大塩町字天神117-2","lat":34.7813399,"lng":134.75797622,"geo_status":"db","era":"天保13／大正後期移築","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0400","desc":"主屋の北西に位置する。桁行９．８ｍ梁間４．９ｍの土蔵造２階建、南北棟の切妻造本瓦葺で、東正面に庇を付ける。白漆喰壁で、正面に腰下見板を張る。内部は南北に二分し、各室に出入口と窓を設ける。庇の持送りや出入口上部に施した文様は丁寧な仕上げになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007774"},{"id":"00007907","register_sub_id":"101","register_pk":"108887","name":"梶原家住宅納屋","kana":"かじわらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77903376,"lng":134.75898432,"geo_status":"db","era":"明治中期／昭和31頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0430","desc":"敷地西辺南寄りに位置する。桁行１３ｍ梁間３．９ｍの木造２階建。南北棟の切妻造本瓦葺で、東面に奥行２．５ｍの桟瓦葺下屋を設ける。壁は中塗仕上げの真壁造で、下屋東面を吹き放つ。内部は１、２階とも２室に分かれ、中塗仕上げ。１階は土間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007907"},{"id":"00007895","register_sub_id":"101","register_pk":"108875","name":"梶原家住宅祠","kana":"かじわらけじゅうたくほこら","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77924329,"lng":134.7595806,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、茅葺、建築面積0.64㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0418","desc":"茶室の北方、川石を二段に組む基壇上に西面して建つ。一間社神明造の社殿。茅葺。横板壁で正面に両開板戸をたて、周囲に縁をまわす。柱は円柱で、妻側には棟持柱を建てる。妻は扠首組を基本とした架構。小規模ながら、丁寧な造りになる本格的な社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007895"},{"id":"00007896","register_sub_id":"101","register_pk":"108876","name":"梶原家住宅南離座敷","kana":"かじわらけじゅうたくみなみはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市大塩町字宮之本457","lat":34.77899538,"lng":134.75933269,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"28-0419","desc":"主屋の南に位置する。東西棟の入母屋造本瓦葺、木造平屋建。八畳と水屋付四畳を東西に並べ、東寄りに檜皮葺庇、西寄りに瓦葺下屋庇を付ける。八畳にはトコとトコ脇、付書院を構え、トコ脇には大きく山道火灯窓を開ける。一崩しの天井など咄々斎写しが見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007896"},{"id":"00007516","register_sub_id":"101","register_pk":"108498","name":"加藤家住宅内蔵","kana":"かとうけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78290225,"lng":134.58614372,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0377","desc":"主屋後方の風呂への縁廊下に面して建つ。桁行４．６ｍ梁間５．７ｍ、土蔵造２階建、切妻造本瓦葺。切石積の基礎に建ち、白漆喰仕上げで、軒は垂木型に塗り込め、水切りより下を海鼠壁とする。東面の２階に小窓を開け、出入口は西面南端で、片引戸をたてる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007516"},{"id":"00007514","register_sub_id":"101","register_pk":"108496","name":"加藤家住宅主屋","kana":"かとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78276941,"lng":134.586136,"geo_status":"db","era":"文久2／明治前期・明治後期改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積279㎡","structure_material":"木造平屋一部2階建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0375","desc":"敷地中央に建つ。桁行２３ｍ梁間１４ｍ、木造平屋建一部２階建、東西棟の入母屋造、本瓦及び桟瓦の錣葺。西寄りを土間とし、床上部は九間取系で正面中央に式台を構える。角座敷である「上ノ間」と土間後方の屋根を落棟として、重厚で変化のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007514"},{"id":"00007518","register_sub_id":"101","register_pk":"108500","name":"加藤家住宅鎮守社","kana":"かとうけじゅうたくちんじゅのやしろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78288107,"lng":134.58632555,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積0.31㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0379","desc":"主屋の東方に鎮座する小祠で、桁行０．５ｍ梁間０．６ｍ、一間社流見世棚造、銅板葺である。花崗岩を積んだ基壇上に据えた土台上に建ち、身舎は円柱を長押で固め、庇は方柱で桁を受ける。身舎は正面に板扉を開き、ほかを横板壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007518"},{"id":"00007519","register_sub_id":"101","register_pk":"108501","name":"加藤家住宅長屋門","kana":"かとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78270328,"lng":134.5863319,"geo_status":"db","era":"元治元／昭和前期改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積96㎡、貴人口付","structure_material":"木造平屋一部2階建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0380","desc":"敷地南辺に建ち、桁行２０ｍ梁間４．７ｍ、木造平屋建一部２階建、切妻造本瓦葺。主屋式台のほぼ正面に門口を構え、東側は二番蔵、西側を物置とする。外壁は白漆喰仕上げで腰を竪板張とし、二番蔵に与力窓、物置に出格子を付し、屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007519"},{"id":"00007521","register_sub_id":"101","register_pk":"108503","name":"加藤家住宅西塀","kana":"かとうけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78265123,"lng":134.5861587,"geo_status":"db","era":"江戸末期／昭和55改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長11m、便所付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0382","desc":"長屋門の物置北側の便所と、北に延びる塀からなり、総延長１１ｍを測る。便所は桁行１．９ｍ梁間２．０ｍ、切妻造桟瓦葺。塀は西側の柱筋を白漆喰壁として腰には竪板を張り、東側柱筋は吹放ちで、一部に大和張の壁を設け、屋根は便所と棟を揃えて桟瓦を葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007521"},{"id":"00007515","register_sub_id":"101","register_pk":"108497","name":"加藤家住宅離れ座敷","kana":"かとうけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78290104,"lng":134.58624769,"geo_status":"db","era":"明治25／明治32・平成16改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0376","desc":"主屋北東に廊下を介して接続する。桁行８．９ｍ梁間４．９ｍ規模の木造平屋建。切妻造桟瓦葺とし、庇屋根を主屋同様に錣屋根とする。内部は丁寧なつくりのトコと書院を備えた続き座敷で、欄間に波兎の透かし欄間を入れる。内庭を望み落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007515"},{"id":"00007517","register_sub_id":"101","register_pk":"108499","name":"加藤家住宅濱座敷","kana":"かとうけじゅうたくはまざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78294117,"lng":134.58609914,"geo_status":"db","era":"嘉永4／明治7増築・昭和33移築改修","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造2階建、瓦葺、建築面積62㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0378","desc":"内蔵に隣接して敷地北辺に位置し、揖保川を西方に望む。桁行７．０ｍ梁間９．７ｍ、木造２階建、入母屋造、本瓦葺及び桟瓦葺。外壁は竪板張及び漆喰塗とし、窓に格子を設ける。周囲に庇を様々な形で廻らし、複雑で特徴的な外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007517"},{"id":"00007520","register_sub_id":"101","register_pk":"108502","name":"加藤家住宅湯殿及び雪隠","kana":"かとうけじゅうたくゆどのおよびせっちん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区余子浜字船渡53-1","lat":34.78272206,"lng":134.586258,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積10㎡、海鼠塀・中門付","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0381","desc":"長屋門の背面に接して建つ。桁行４．２ｍ梁間２．７ｍ、切妻造桟瓦葺で、円形や八角形の下地窓など数寄屋風の意匠をもつ。西面の海鼠壁を北に延ばして海鼠塀とし、切石を鳥居型に組んだ中門を挟んで主屋の式台脇に至る。特徴的な外観で庭空間を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007520"},{"id":"00000143","register_sub_id":"101","register_pk":"101133","name":"川西市郷土館（旧平安家住宅離れ）","kana":"かわにしきょうどかん（きゅうひらやすけじゅうたくはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89806972,"lng":135.40908361,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積44㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0007","desc":"敷地西面に建つ数寄屋風の造りになる平屋建物で，南及び東面に１間の縁が付く。平面は床構えのある南座敷とその奥の控えの間からなる。吟味された上質の材料を用いた丁寧な造りになり，小規模ながら大正期の和風建築の技術の高さを知る上での好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000143"},{"id":"00000150","register_sub_id":"101","register_pk":"101140","name":"川西市郷土館（旧平安家住宅北納屋）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくきたなや）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89815157,"lng":135.40931971,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建屋根塀付，瓦葺，建築面積15㎡","structure_material":"木造平屋建屋根塀付","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0014","desc":"敷地の北側に建つ板壁の納屋で，東側に延びる瓦屋根付きの高塀が付設する。内部は一室の土間とし，全体として簡素な造りになる。小規模な建物ながら，切妻屋根の南流れは腕木を付けて屋根を受ける。屋敷地の奥向きの空間構成を知る上で必要な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000150"},{"id":"00000142","register_sub_id":"101","register_pk":"101132","name":"川西市郷土館（旧平安家住宅玄関）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくげんかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89783834,"lng":135.40920481,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積41㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0006","desc":"主屋の南面に建つ入母屋造，平入の平屋建物で四方に庇が付く。平面は，東端を通路を兼ねる土間とし背後に内玄関を置き，西側に接客空間としての広間及び控えの間を配する。主屋から接客部分が分離した近代的な要素が入り込む大正期の住宅建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000142"},{"id":"00000145","register_sub_id":"101","register_pk":"101135","name":"川西市郷土館（旧平安家住宅玄関門）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくげんかんもん）","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89776279,"lng":135.40929768,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"一間薬医門屋根塀付，瓦葺","structure_material":"一間薬医門屋根塀付","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0009","desc":"玄関棟の東脇にある切妻造，瓦葺の一間薬医門で，左右に袖壁が付く。左袖壁は，潜り戸付きになるが，右袖壁は矩折れとなって玄関棟に接続する。小規模ではあるが，細部に至るまで洗練された技法になる大正期の基準的な作品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000145"},{"id":"00000078","register_sub_id":"101","register_pk":"101068","name":"川西市郷土館（旧平安家住宅主屋）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財字上の町８","lat":34.89795218,"lng":135.40920107,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"28 － 0004","desc":"平安家は銅の精錬で栄えた家で，旧宅は土間と２列３室からなる伝統的な６間取りを基調として，屋根や庇等に数寄屋風の意匠を，玄関脇の接客部分等に近代的な間取りを取り入れている。伝統的手法を継承し要所に変化を加えた大正期の大規模邸宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000078"},{"id":"00000149","register_sub_id":"101","register_pk":"101139","name":"川西市郷土館（旧平安家住宅長屋門）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくながやもん）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89803667,"lng":135.40940156,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建屋根塀付，瓦葺，建築面積36㎡","structure_material":"木造平屋建屋根塀付","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0013","desc":"敷地の東面北寄りに建つ標準的な長屋門で，北側に瓦屋根付きの高塀が連なる。家人の日常的な出入り口として設けられたものであるが，現在は左右の部屋は便益施設に一部改造されている。外壁は内法下を板張りとし，付設の塀とも屋敷地の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000149"},{"id":"00000154","register_sub_id":"101","register_pk":"101144","name":"川西市郷土館（旧平安家住宅西蔵）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくにしぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.8981075,"lng":135.40908991,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積22㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0018","desc":"離れ座敷の北側に建つ平面正方形の土蔵で，離れや乾蔵とともに屋敷地の西側を限る。瓦屋根を置屋根とした造りになり，外観は北蔵や乾蔵と同じく軒蛇腹を設け軒を飾る。整然とした外観の土蔵で，大正期の屋敷構えを構成する要素として位置づけられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000154"},{"id":"00000153","register_sub_id":"101","register_pk":"101143","name":"川西市郷土館（旧平安家住宅西納屋）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくにしなや）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89813898,"lng":135.40909463,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積9.4㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0017","desc":"乾蔵と西蔵との間に付設された小規模な納屋で，極めて簡素な構造になる。内部は一室で，正面は間口いっぱいに引き違い戸を置く。重厚な土蔵群の中にあって簡素な建物ではあるが，中庭を囲う一群の土蔵等の建物の一つとして構成上必要な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000153"},{"id":"00000147","register_sub_id":"101","register_pk":"101137","name":"川西市郷土館（旧平安家住宅南納屋）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくみなみなや）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89780372,"lng":135.40935749,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積22㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0011","desc":"巽蔵の北側に接して建つ切妻造，平屋建の納屋で，北側に井戸屋が付設する。内部は一室の板敷きの間とする。全体的に簡素な造りであるが，大規模邸宅の屋敷構えを構成する一つの要素として，また大正期の生活空間を知る上でも必要な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000147"},{"id":"00000155","register_sub_id":"101","register_pk":"101145","name":"川西市郷土館（旧平安家住宅屋根塀）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくやねべい）","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89786565,"lng":135.40905467,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"瓦葺，延長48.2m","structure_material":"瓦葺","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0019","desc":"屋敷地西南部にあり，玄関アプローチの左側面から座敷の西南角に至る間に設けられた瓦屋根付きの板塀。総延長４８．２ｍあり，簡素ながら風格ある堂々とした板塀である。大正期における大邸宅の前面を囲う塀の好例として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000155"},{"id":"00000144","register_sub_id":"101","register_pk":"101134","name":"川西市郷土館（旧平安家住宅浴室）","kana":"かわにししきょうどかん（きゅうひらやすけじゅうたくよくしつ）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89810907,"lng":135.40919537,"geo_status":"db","era":"大正7～8","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積31㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0008","desc":"主屋の背後に独立して建つ切妻造，瓦葺の小規模な建物で，気抜きの小屋根が付く。平面は，浴室と脱衣室からなり，主屋とは瓦屋根付きの渡り廊下で接続する。全体的には簡素な造りであるが，大正期の上層の町家の生活空間を知る上で貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000144"},{"id":"00004599","register_sub_id":"101","register_pk":"105589","name":"神田家住宅洋館","kana":"かんだけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加古川市加古川町本町字北側444-3","lat":34.77021886,"lng":134.83261678,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造及び鉄筋コンクリート造地上2階地下1階建、建築面積58㎡","structure_material":"煉瓦造及び鉄筋コンクリート造地上2階地下1階建","registered":"2005.02.09(平成17.02.09)","register_no":"28 － 0187","desc":"旧山陽道に面した細長い敷地のほぼ中央にある。外壁モルタル塗のため，外観からはＲＣ造にみえるが，煉瓦造とＲＣスラブによる混構造２階建で，１階を１０畳の和室，２階を１２畳の洋室とする。玄関や縦長の上げ下げ窓等には，洋風の素朴な意匠が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004599"},{"id":"00009514","register_sub_id":"101","register_pk":"194307","name":"岸本家別邸主屋","kana":"きしもとけべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市垂水区海岸通2160-5","lat":34.6279529,"lng":135.0514779,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積302㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0553","desc":"垂水駅近くの海岸沿いに構えた広大な屋敷地の中央に建つ。木造二階建、建築面積三〇二平方メートル、入母屋造及び寄棟造桟瓦葺で、北面中央に唐破風造の玄関を出す。内部は、材料と意匠を凝らした数寄屋造で仕上げる。財界人が営んだ上質な別荘建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009514"},{"id":"00009515","register_sub_id":"101","register_pk":"194308","name":"岸本家別邸離れ","kana":"きしもとけべっていはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市垂水区海岸通2160-5","lat":34.62777254,"lng":135.05147171,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積182㎡、渡廊下付","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0554","desc":"主屋の南側に建ち、渡廊下で接続する。木造平屋建、建築面積一九〇平方メートル、入母屋造桟瓦葺で、南側の庭園に面して各部屋を配する。内部は書院造を基調に、十五畳広間の床を寄木張とするなど近代的な要素を併せもつ。主屋とともに別荘建築の中心をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009515"},{"id":"00003127","register_sub_id":"101","register_pk":"104117","name":"北野物語館（旧Ｍ．Ｊ．シェー邸）","kana":"きたのものがたりかん（きゅうえむ.じぇー.しぇーてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市中央区北野町3-1-31","lat":34.69983114,"lng":135.19023359,"geo_status":"db","era":"明治40／平成13移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"28 － 0113","desc":"木造２階建，桟瓦葺，寄棟屋根，下見板張の洋館。阪神・淡路大震災後に解体されたが，平成１３年に現在地に移築され，店舗兼資料館として活用されている。オリエル・ウィンドウを備える点や平面配置などに特徴があり，小規模洋館の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003127"},{"id":"00013426","register_sub_id":"101","register_pk":"368511","name":"旧芦屋市営宮塚町住宅","kana":"きゅうあしやしえいみやづかちょうじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県芦屋市宮塚町89-1","lat":34.73131944,"lng":135.31018333,"geo_status":"db","era":"昭和28年／平成30年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"石造2階建、建築面積177㎡","structure_material":"石造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"28 － 0742","desc":"芦屋駅南東に位置する、戦後の住宅不足対策で建てられたもと市営住宅。公営住宅標準設計52ＦＣ型を基本とするが、外壁は凝灰岩とコンクリートブロックを交互に積重ねる。間取は台所と居室二室からなる。戦後復興期の地方公営住宅の様相を示す希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013426"},{"id":"00016415","register_sub_id":"101","register_pk":"536482","name":"旧安藤家住宅主屋","kana":"きゅうあんどうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県明石市材木町4-23","lat":34.64441111,"lng":134.98873333,"geo_status":"db","era":"大正11年／昭和前期増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積147㎡、西門及び塀付","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0843","desc":"明石港西岸部に位置し、製粉業を営んだ商家の主屋。角地に建つ二階建入母屋造平入桟瓦葺で一階正面は犬矢来構え、二階外壁は漆喰塗大壁で定規筋を付し、軒裏を現す。二階隅は洋室で縦長窓を開ける。一階から立上げた巨大な袖卯建が目を惹く豪壮な構えの町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016415"},{"id":"00016417","register_sub_id":"101","register_pk":"536484","name":"旧安藤家住宅土蔵","kana":"きゅうあんどうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県明石市材木町4-23","lat":34.64428889,"lng":134.98867778,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0845","desc":"主屋南西に位置する家財蔵。切石積基壇に建つ二階建切妻造妻入で北に戸口を設ける。外壁は漆喰塗仕上で軒まで塗込め、鉢巻を廻らし、腰は高く竪板を張る。内部は各階一室の板敷で小屋組は和小屋。通りに面し重厚な外観で、地域の歴史的な景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016417"},{"id":"00016416","register_sub_id":"101","register_pk":"536483","name":"旧安藤家住宅離れ","kana":"きゅうあんどうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県明石市材木町4-23","lat":34.64428889,"lng":134.98875278,"geo_status":"db","era":"大正11年頃／昭和中期増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積46㎡、南面板塀付","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0844","desc":"主屋南東に位置する座敷棟。平屋建片入母屋造桟瓦葺、軒先銅板葺とした南北棟で、北西で主屋廊下に接続し、南に増築の洋室を附属。北面に縁を付し、室内は大壁で洋風を基調としつつ、縁境に煤竹格子の欄間や丸窓などを配し、和風を加味した折衷意匠の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016416"},{"id":"00015493","register_sub_id":"101","register_pk":"533508","name":"旧岩本家住宅茶室（大手前大学茶室竹立庵）","kana":"きゅういわもとけじゅうたくちゃしつ（おおてまえだいがくちゃしつちくりゅうあん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市郷免町1-1","lat":34.73770833,"lng":135.3245,"geo_status":"db","era":"昭和前期／平成4年移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"28 - 0842","desc":"大手前大学のキャンパス内に位置する旧実業家の茶室。切妻造桟瓦葺の北・南棟で、軒先銅板葺、北辺に銅板葺庇を付して屋根に変化を付ける。内部南半に水屋と待合、北半に半床庵の写しと伝わる茶室を配す。キャンパス前身の邸宅の歴史を留める上質な茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015493"},{"id":"00007655","register_sub_id":"101","register_pk":"108637","name":"旧大西家住宅（みとろ苑）大広間棟","kana":"きゅうおおにしけじゅうたく（みとろえん）おおひろまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加古川市上荘町見土呂字尾375-1","lat":34.800682,"lng":134.898727,"geo_status":"db","era":"大正7頃","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0391","desc":"敷地西北に位置し、南北を庭園に囲まれる。東西棟の入母屋造桟瓦葺、背面に入母屋屋根を出し、周囲に銅板庇をめぐらす。十六畳の大広間と次の間を東西に並べ、三方に畳縁をまわし、角座敷を付設。厳選された良材が使われ、座敷構えや繊細な欄間など見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007655"},{"id":"00007657","register_sub_id":"101","register_pk":"108639","name":"旧大西家住宅（みとろ苑）表門","kana":"きゅうおおにしけじゅうたく（みとろえん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加古川市上荘町見土呂字尾375-1","lat":34.800392,"lng":134.898972,"geo_status":"db","era":"大正後期／昭和中期改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口4.9m、東側塀付","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0393","desc":"通りに南面する切妻造の門で、東西に塀を付ける。桁行三間で、両端には控柱を建てる。中央に両開戸をたて、上部に小壁を設け、両脇間及び本柱控柱間を腰竪板張、上部土壁とし、東脇間に潜りを設ける。背面に聚楽壁を残す。軽快ながら品格のある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007657"},{"id":"00007656","register_sub_id":"101","register_pk":"108638","name":"旧大西家住宅（みとろ苑）渡廊下及び浴室","kana":"きゅうおおにしけじゅうたく（みとろえん）わたりろうかおよびよくしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加古川市上荘町見土呂字尾375-1","lat":34.80067837,"lng":134.8989203,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺及び銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0392","desc":"大広間棟から東南方へ矩折れに延び、北面に浴室などを付設。切妻造桟瓦及び銅板葺で、磨丸太材を使用。土壁とし、隅切りの方形窓や木瓜窓を開ける。浴室天井は中央に換気口を設け、放射状に棹縁を配り、脱衣室は舟底天井とする。数寄屋風意匠になる瀟洒な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007656"},{"id":"00010985","register_sub_id":"101","register_pk":"208955","name":"旧鍵野家住宅主屋","kana":"きゅうかぎのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区御影二丁目325-7","lat":34.723441,"lng":135.249257,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建一部地階付、瓦葺、建築面積100㎡","structure_material":"木造2階建一部地階付","registered":"2016.02.25(平成28.02.25)","register_no":"28-0642","desc":"御影の傾斜のある住宅街に建つ洋館。屋根にドーマー窓を上げ、外壁の一部をドイツ壁仕上げとした下見板張の洋風外観とする。一階を応接室や書斎などの洋室とし、二階に和室を並べる。貿易港神戸における戦前期中産階級のための住宅のあり方を良く示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010985"},{"id":"00002675","register_sub_id":"101","register_pk":"103665","name":"旧来住家住宅客湯殿","kana":"きゅうきしけじゅうたくきゃくゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県西脇市西脇394-1","lat":34.98706941,"lng":134.97216646,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0094","desc":"主屋の西北方，離れの北方に位置し，渡廊下により主屋と離れに連絡する。南北棟，桟瓦葺，入母屋造で，南から化粧室，湯殿，便所及び手洗から成る。数寄屋風のつくりで，湯殿の腰と床にはタイルが貼られ，洗面台の台板は大理石，手洗は人造石仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002675"},{"id":"00002673","register_sub_id":"101","register_pk":"103663","name":"旧来住家住宅主屋","kana":"きゅうきしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県西脇市西脇394-1","lat":34.98710582,"lng":134.97231273,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積242㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0092","desc":"外観はつし２階に虫籠窓を開けた伝統的形式を採るが，内部には中廊下型に近い間取や，軒や鴨居の垂下がり防止用に桔木や鉄棒を使用するなど近代的手法が採られている点に特徴がある。また，銘木や吟味された良材がふんだんに用いられていることも特筆される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002673"},{"id":"00002674","register_sub_id":"101","register_pk":"103664","name":"旧来住家住宅離れ","kana":"きゅうきしけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県西脇市西脇394-1","lat":34.98718968,"lng":134.97218795,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0093","desc":"主屋西南方に主屋に先立って建設。南北棟，桟瓦葺，入母屋造で，床の間・棚・付書院をもつ８畳座敷と８畳の次の間から成り，南・東・北の３面に縁廊下を廻す。棟梁は主屋と同じ足立久治で，主屋と同様に銘木や吟味された木目の良材を適所に使用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002674"},{"id":"00005017","register_sub_id":"101","register_pk":"106007","name":"旧吉川家住宅（生野まちづくり工房井筒屋）内蔵","kana":"きゅうきっかわけじゅうたく（いくのまちづくりこうぼういづつや）うちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷640","lat":35.16648384,"lng":134.79451289,"geo_status":"db","era":"天保14","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造2階建、瓦葺、建築面積22㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0211","desc":"主屋北西隅に接続している２階建で，１階は納戸，２階は床付の座敷とする。屋根は南北棟の切妻造，桟瓦葺，南面は１階に下屋，２階窓には銅板葺の小庇をつける。外壁は土壁で軒裏まで塗り，縦板張で覆う。大規模な屋敷における住まいの有様の一端を示す施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005017"},{"id":"00005018","register_sub_id":"101","register_pk":"106008","name":"旧吉川家住宅（生野まちづくり工房井筒屋）米蔵","kana":"きゅうきっかわけじゅうたく（いくのまちづくりこうぼういづつや）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷640","lat":35.1665199,"lng":134.79451524,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積19㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0212","desc":"土蔵造平屋建，置屋根式の切妻造で，屋根は桟瓦葺とする。外壁は土壁，各面を縦板張で覆い，頂部に鉢巻を廻す。１階は東面中央に扉口，２階は妻面に板庇付小窓を設ける。内部は高い室内空間を造る。敷地の北西隅にあり，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005018"},{"id":"00005014","register_sub_id":"101","register_pk":"106004","name":"旧吉川家住宅（生野まちづくり工房井筒屋）主屋","kana":"きゅうきっかわけじゅうたく（いくのまちづくりこうぼういづつや）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷640","lat":35.16639924,"lng":134.79449759,"geo_status":"db","era":"天保3","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積159㎡","structure_material":"木造2階一部平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0208","desc":"西が入母屋造，東が切妻造となる東西棟の２階建で，下屋を設け，屋根は桟瓦葺，外壁は土壁とする。内部は東が土間，西が３室を二列に配し，西面中央の座敷に床・棚を構え，茶の間等は梁組を現す。街路沿いにあり，幕末期の町並景観を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005014"},{"id":"00005016","register_sub_id":"101","register_pk":"106006","name":"旧吉川家住宅（生野まちづくり工房井筒屋）土蔵","kana":"きゅうきっかわけじゅうたく（いくのまちづくりこうぼういづつや）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷640","lat":35.16634108,"lng":134.7945728,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0210","desc":"土蔵造２階建，置屋根式の切妻造で，屋根は桟瓦葺とする。外壁は土壁で，縦板張で覆い，頂部に鉢巻を廻すが，西面は中央に観音開扉を開き，壁面も白漆喰塗とする。２階は妻面に白漆喰で縁取った小窓を設ける。敷地南東隅の街路沿いにあり，景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005016"},{"id":"00005019","register_sub_id":"101","register_pk":"106009","name":"旧吉川家住宅（生野まちづくり工房井筒屋）西塀","kana":"きゅうきっかわけじゅうたく（いくのまちづくりこうぼういづつや）にしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷640","lat":35.16648695,"lng":134.79446169,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長21m、門付","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0213","desc":"屋敷西辺，主屋の南西隅から米蔵まで達する鍵型の塀。折曲がり約２１ｍで，南面の主屋寄りには１間腕木門を構える。外壁は漆喰塗で，腰を縦板張で覆い，腕木で桁を受けて桟瓦葺屋根を架ける。主屋西の庭を取り囲むとともに，敷地廻りの街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005019"},{"id":"00005015","register_sub_id":"101","register_pk":"106005","name":"旧吉川家住宅（生野まちづくり工房井筒屋）離れ","kana":"きゅうきっかわけじゅうたく（いくのまちづくりこうぼういづつや）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷640","lat":35.16638484,"lng":134.79458305,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0209","desc":"主屋東面の北寄りに接続する。真壁造，平屋建で，屋根は切妻造，桟瓦葺，和小屋を組み，南・東・北の３面に下屋を廻す。内部はもと座敷２室であったが，現在は１室とする。軸組等はよく残り，外観も主屋と調和がとれた構成で，明治期の離れの形式を示してる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005015"},{"id":"00016571","register_sub_id":"101","register_pk":"574933","name":"旧斎藤家住宅主屋（千鳥屋宗家薬師山山荘）","kana":"きゅうさいとうけじゅうたくおもや（ちどりやそうけやくしやまさんそう）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県丹波篠山市東吹字西山184他","lat":34.69130833,"lng":135.18299444,"geo_status":"db","era":"安政3年（1856）／平成4年移築","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0858","desc":"篠山城下の町人地から移築した旧油商の主屋。敷地中央に西面して建つ、つし二階建切妻造平入桟瓦葺で、正面に大戸と出格子を構え、外壁は漆喰塗仕上で軒まで塗り込める。内部は北に土間、南に２列６室を配す。内外ともに当初形式を良く残す幕末の町家遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016571"},{"id":"00013425","register_sub_id":"101","register_pk":"368510","name":"旧坂家住宅主屋","kana":"きゅうさかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区再度筋町1-6","lat":34.69517222,"lng":135.177125,"geo_status":"db","era":"大正11年／平成23年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造一部煉瓦造2階一部平屋建、瓦葺一部銅板葺、建築面積253㎡","structure_material":"木造一部煉瓦造2階一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"28 － 0741","desc":"市内中心部の高台に建つ。木造2階建の和館の東側に煉瓦造平屋建の洋館が附属する。端正な外観の洋館に照り起り屋根の玄関を付して、内外の要所に海や船を題材としたステンドグラスを嵌める。瀟洒な佇まいは政財界人が邸宅を構えた当地の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013425"},{"id":"00013152","register_sub_id":"101","register_pk":"368293","name":"旧高碕家住宅主屋（高碕記念館）","kana":"きゅうたかさきけじゅうたくしゅおく（たかさききねんかん）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘一丁目56","lat":34.82848333,"lng":135.40008056,"geo_status":"db","era":"大正12年頃／昭和8年頃・同13年頃・同37年・平成2年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造3階建一部地階付、スレート葺、建築面積170㎡","structure_material":"木造3階建一部地階付","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0719","desc":"阪急雲雀丘花屋敷駅北側の住宅地にあり、道路に西面して建つ。東西棟のダッチコロニアル風腰折屋根で、平側中央は二階壁面が張出す。正面に玄関ポーチを付して妻に縦長窓を並べ、外壁はドイツ壁風の仕上げ。内部は中廊下式の平面。地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013152"},{"id":"00016420","register_sub_id":"101","register_pk":"536487","name":"旧髙原家住宅奥座敷","kana":"きゅうたかはらけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県加西市西剱坂町字村中780","lat":34.89416667,"lng":134.80221944,"geo_status":"db","era":"明治22年／明治後期増築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0848","desc":"市街地南部の農村集落に位置する旧家の座敷棟。敷地西側に建つ入母屋造桟瓦葺の南北棟で、北に便所棟を附属する。内部は続き間座敷で、南庭に面して縁を廻らし、銅板葺の下屋を付す。床と床脇に天袋付の清楼棚、付書院を備え、室境の透欄間など上質な座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016420"},{"id":"00016421","register_sub_id":"101","register_pk":"536488","name":"旧髙原家住宅中座敷","kana":"きゅうたかはらけじゅうたくなかざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県加西市西剱坂町字村中780","lat":34.89418333,"lng":134.80232222,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0849","desc":"奥座敷の北東に接続する座敷棟。敷地北側に建つ入母屋造桟瓦葺の南北棟で、外壁は漆喰塗で軒まで塗込める。内部は十畳の一室で、西面に床と床脇を構え、四周に縁を廻らし、桟瓦葺の下屋を付す。壁を色土壁、床柱に赤マツの皮付丸太など用材を吟味した座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016421"},{"id":"00015491","register_sub_id":"101","register_pk":"533506","name":"旧田中家住宅別邸主屋","kana":"きゅうたなかけじゅうたくべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市西新町字カントウシ125-4","lat":34.83646111,"lng":134.67942222,"geo_status":"db","era":"昭和8年／昭和後期改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積74㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"28 - 0840","desc":"姫路城西方の龍野に位置し、金物や煙草の製造販売を営んだ商家の大塀造の別邸。通りより控えて建つ二階建入母屋造桟瓦葺で、南に平屋を附属する。二階は続き間座敷で東・南に縁を廻らし、東面北寄りに高欄を付す。床柱にスギの磨丸太を用いるなど上質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015491"},{"id":"00015492","register_sub_id":"101","register_pk":"533507","name":"旧田中家住宅別邸門及び塀","kana":"きゅうたなかけじゅうたくべっていもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市西新町字カントウシ125-4他","lat":34.83643333,"lng":134.67946944,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"門 木造、瓦葺、間口1.5m、左右袖塀付 塀 木造、瓦葺、総延長12m","structure_material":"門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"28 - 0841","desc":"主屋の前栽を囲繞し、通りに東面して建つ門及び塀。北寄りに開く門は軒先銅板葺の桟瓦葺庇を付し、門口に吹寄格子戸を建て、上部は筬欄間とする。塀は桟瓦葺で、外壁漆喰塗仕上、腰は竪板張。格狭間に竹の組子を用いる凝った意匠の塀で、通りの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015492"},{"id":"00002677","register_sub_id":"101","register_pk":"103667","name":"旧玉置家住宅北土蔵","kana":"きゅうたまおきけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-454","lat":34.79885262,"lng":134.98378072,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0096","desc":"主屋土間から奥に連なる通り庭風の便益棟の突き当たりに位置し，洪水対策用の石積基壇上に建つ。東西棟，桟瓦葺，切妻造，平入の２階建土蔵で，桁行２間半，梁間３間半規模。窓開口は当地方特有の丸形で，離れなどともに美嚢川沿いに特色ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002677"},{"id":"00002676","register_sub_id":"101","register_pk":"103666","name":"旧玉置家住宅主屋","kana":"きゅうたまおきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県三木市本町2-454","lat":34.79869583,"lng":134.98403179,"geo_status":"db","era":"江戸末期／明治後期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0095","desc":"三木城下の中心地，旧街道と美嚢川に挟まれた南北に長い敷地の南寄り街道沿いに南面して建つ。表屋造風のつくりで，塗屋，つし２階の町家風玄関棟と奥の座敷棟を式台玄関が繋ぐ。座敷棟は東側を土間とし，上手の座敷２室を上段にしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002676"},{"id":"00002679","register_sub_id":"101","register_pk":"103669","name":"旧玉置家住宅西土蔵","kana":"きゅうたまおきけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-454","lat":34.798756,"lng":134.983917,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0098","desc":"主屋座敷棟の西側増築部の北方に位置する。桁行３間，梁間２間半規模，南北棟，本瓦葺，切妻造，妻入の２階建土蔵で，南妻面東半部と増築部北面との間に台形平面の板間の蔵前をつくる。西側隣接地に所在する蔵で，玉置家敷地の拡張過程を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002679"},{"id":"00002680","register_sub_id":"101","register_pk":"103670","name":"旧玉置家住宅離れ","kana":"きゅうたまおきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-454","lat":34.798878,"lng":134.983887,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0099","desc":"主屋座敷棟の北方，北土蔵の西に位置する。桁行２間半，梁行５間規模，東西棟，桟瓦葺，緩やかな起りをつけた切妻造の木造２階建で，床の間・棚・付書院をもつ８畳座敷と８畳次の間の２室構成になり，南北両面に縁側を付け，川側に塀で囲われた庭園を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002680"},{"id":"00002678","register_sub_id":"101","register_pk":"103668","name":"旧玉置家住宅東土蔵","kana":"きゅうたまおきけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-454","lat":34.79891362,"lng":134.98391534,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積9.9㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0097","desc":"北土蔵の南方，便益棟の北端に位置し，北土蔵との間に裏門を設ける。石積基壇上に建つ南北棟，本瓦葺，切妻造，妻入の２階建土蔵で，中庭側の外壁腰は海鼠壁とする。桁行２間，梁間１間半規模の道具蔵で，「六畳の蔵」と呼ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002678"},{"id":"00002681","register_sub_id":"101","register_pk":"103671","name":"旧玉置家住宅廊下","kana":"きゅうたまおきけじゅうたくろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-454","lat":34.798813,"lng":134.983948,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積8.2㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0100","desc":"主屋座敷棟と離れを結ぶ。長５間半で，西側に南から物入・便所・浴室・物入を並べ，東側を吹放ち廊下とする。西面外観は高塀的な造りで瓦葺とするが，廊下部は軽快な銅板葺とし，主屋座敷縁側，離れ南縁側とともに，東側の便益棟との間に開放的な中庭を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002681"},{"id":"00010488","register_sub_id":"101","register_pk":"199436","name":"旧中和家住宅主屋","kana":"きゅうなかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県豊岡市出石町三木字廣畑133-2","lat":35.481979,"lng":134.832416,"geo_status":"db","era":"江戸中期／昭和6年・平成25年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"28 － 0607","desc":"屋敷中央に東面して建つ。桁行九間規模で居室部は前後三室ずつ並べ、式台玄関を持つ。二階は昭和六年に増築された養蚕部屋で越屋根を設ける。一階部分は但馬地域最古級の大型民家遺構であり、近代の養蚕振興に伴う形式変遷も窺え、地域の歴史的景観の核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010488"},{"id":"00012225","register_sub_id":"101","register_pk":"353025","name":"旧西垣家住宅旧納屋","kana":"きゅうにしがきけじゅうたくきゅうなや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市柏原町柏原字竪町588","lat":35.128341,"lng":135.080716,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積46㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"28-681","desc":"主屋の東方に西面して建つ。桁行七・八メートル、梁間四・九メートルの切妻造で、西面と南面に下屋を設ける。外壁は真壁で、半間毎に窓を設ける。後に床を張り、北端に二階を設けアトリエとして使用された。敷地後方の屋敷構えを構成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012225"},{"id":"00012224","register_sub_id":"101","register_pk":"353024","name":"旧西垣家住宅主屋","kana":"きゅうにしがきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市柏原町柏原字竪町588","lat":35.128341,"lng":135.080549,"geo_status":"db","era":"明治後期／昭和40年代増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"28-680","desc":"旧武家地に西面して建つ。木造二階建、入母屋造で、正面二階に縦長の虫籠窓を三箇所開き、軒まで塗り込め整った外観。一階は通り土間に沿って二列五室を配す。軸部は木太く堅牢な造りで、座敷は廻縁や天井の棹縁に面皮材を用い、数寄屋風の意匠も取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012224"},{"id":"00012226","register_sub_id":"101","register_pk":"353026","name":"旧西垣家住宅塀","kana":"きゅうにしがきけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市柏原町柏原字竪町588","lat":35.128234,"lng":135.080526,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長38m、門付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"28-682","desc":"主屋正面から座敷前の庭園を囲み、敷地後方の畑地を区画する塀。北面と東面に出入口を設け、舞良戸をたてる。木造、真壁造で、外側を腰板張、上部漆喰塗とし、腕木で軒桁を受け切妻造の屋根を架ける。良好な庭園景観を作り、街路からの歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012226"},{"id":"00012780","register_sub_id":"101","register_pk":"367683","name":"旧平賀家住宅東屋","kana":"きゅうひらがけじゅうたくあずまや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町41-16","lat":34.89704889,"lng":135.40962194,"geo_status":"db","era":"大正8年頃／平成元年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄骨造、スレート葺、面積49㎡","structure_material":"鉄骨造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 715","desc":"市中心部から移築した科学者・平賀義美自邸のガゼボ（洋風東屋）。六角形平面の各角に鋳鉄製の円柱を立て、六角錐スレート葺の屋根をかける。柱間に腰板と硝子欄間を嵌め、コンクリート洗出しの床面に星形の目地を切る。上質な意匠をもつ近代住宅の附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012780"},{"id":"00000156","register_sub_id":"101","register_pk":"101146","name":"旧平賀家住宅実験研究棟","kana":"きゅうひらがけじゅうたくじっけんけんきゅうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財町4-1","lat":34.89827938,"lng":135.40969045,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建，スレート葺，建築面積32㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"28 － 0020","desc":"化学者であった施主のための実験施設を収容する。主屋と比較すると簡素な外観であるが，ファサードの構成等に主屋との一貫性が見られる。主屋と階段状の空中廊下で２階部分が接続されており，色彩的にも主屋と対照をなす建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000156"},{"id":"00000079","register_sub_id":"101","register_pk":"101069","name":"旧平賀家住宅主屋","kana":"きゅうひらがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県川西市下財字上の町８","lat":34.89817293,"lng":135.40962476,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積152㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"28 － 0005","desc":"英国に留学経験のある施主が英国のカントリーハウスにならい建てたもので，設計が大林組の松本兎象，施工が鴻池組である。屋根勾配，出窓，暖炉，煙突等の各所にその様子が表れており，19世紀末から流行する本格的な洋風邸宅の大正期における好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000079"},{"id":"00014282","register_sub_id":"101","register_pk":"509672","name":"旧藤森家住宅勝手門","kana":"きゅうふじもりけじゅうたくかってもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83390278,"lng":134.68034444,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、瓦葺、間口1.5m","structure_material":"木造","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0787","desc":"敷地の北面東で本館の勝手口に通じる門。一間腕木門で屋根は切妻造桟瓦葺。本柱を節付の丸太、控柱は名栗仕上の材とし、ガラス格子戸を引違で建て込む。欄間は竹の横桟とし、中央にガラス箱の照明をはめ込むなど、数寄屋風の意匠に近代的な実用性を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014282"},{"id":"00014277","register_sub_id":"101","register_pk":"509667","name":"旧藤森家住宅西方庵","kana":"きゅうふじもりけじゅうたくさいほうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83392222,"lng":134.67998056,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0782","desc":"敷地北西部で庭園に南面する茶室。六畳茶室、四畳半次の間、水屋からなり、屋根は入母屋造桟瓦葺で庭園側に銅板葺の庇を廻らす。茶室は全面竹簾の舟底天井で庭園に向け障子戸の大開口を取るなど開放的で、次の間へは露地を屋内に引き込む特徴的な構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014277"},{"id":"00014276","register_sub_id":"101","register_pk":"509666","name":"旧藤森家住宅産殿","kana":"きゅうふじもりけじゅうたくさんでん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83389444,"lng":134.68023333,"geo_status":"db","era":"昭和10年頃／同15年移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0781","desc":"本館の北に建つ。元は市内旧濱本家住宅別邸にあり賀陽宮恒憲王妃の出産に当てられた産殿。平屋建入母屋造桟瓦葺で、西から床構え付書院付き八畳と六畳を並べて南に縁を付し、東に廊下と洋室を付す。南縁は大判のガラス戸を建て高欄を付す。貴重な産殿の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014276"},{"id":"00014280","register_sub_id":"101","register_pk":"509670","name":"旧藤森家住宅雪隠","kana":"きゅうふじもりけじゅうたくせっちん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83383333,"lng":134.68013056,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0785","desc":"待合の東に隣接して建つ雪隠。平面はおよそ一メートル四方の小規模な建物で、北西隅を斜めに切り欠き片開出入口扉を付す。屋根は招き屋根の杉皮葺で、内外壁は錆壁とし、北面に下地窓を開け、内部南寄りに陶器製の小便器を置く。待合と一連で景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014280"},{"id":"00014275","register_sub_id":"101","register_pk":"509665","name":"旧藤森家住宅本館","kana":"きゅうふじもりけじゅうたくほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83375833,"lng":134.680225,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積232㎡","structure_material":"木造2階一部平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0780","desc":"姫路市中心市街地に建つ海老原一郎設計の医家の本館。木造二階建外壁モルタル塗の住宅で、座敷廻りに洗練された数寄屋風の材料、意匠を用いる。鉄平石敷ポーチ付の玄関、直線的意匠の多用、水平連続窓の洋風応接室など、建築家らしい工夫も随所に見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014275"},{"id":"00014279","register_sub_id":"101","register_pk":"509669","name":"旧藤森家住宅待合","kana":"きゅうふじもりけじゅうたくまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83384722,"lng":134.68010833,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0784","desc":"本館西、茶室との間に建つ待合。平面は南半を磚敷の腰掛待合、北半を土間、三畳座敷、水屋とする。屋根は切妻造桟瓦葺で、腰掛待合の庇は杉皮大和葺でひしぎ竹の化粧屋根裏とし、三畳座敷は煤竹の割竹天井にすさを散らした土壁とするなど趣向を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014279"},{"id":"00014278","register_sub_id":"101","register_pk":"509668","name":"旧藤森家住宅水屋","kana":"きゅうふじもりけじゅうたくみずや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83398056,"lng":134.67989444,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0783","desc":"茶室の西に建つ独立の水屋。平屋建切妻造桟瓦葺の押入付六畳に、北側を落棟の土間、その東西に雪隠、物置をそれぞれ突出させる。磨き丸太の棟木や桁を用いる上質な造りで、真壁造中塗仕上で腰は屋敷側を杉皮張、街路側を竪板張として歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014278"},{"id":"00014281","register_sub_id":"101","register_pk":"509671","name":"旧藤森家住宅露地門","kana":"きゅうふじもりけじゅうたくろじもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市船橋町三丁目2","lat":34.83396111,"lng":134.68008889,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、瓦葺、間口1.6m","structure_material":"木造","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0786","desc":"敷地北面に街路から引き込んで建つ露地門。一間腕木門で両開き板戸を建て込む。屋根は切妻造桟瓦葺、欄間は土壁塗。本柱は節付の丸太、控柱は名栗仕上の材を用い、磨き丸太の棟木や桁と杉丸太垂木、竹の間垂木など、数寄屋風意匠で茶室への露地を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014281"},{"id":"00007522","register_sub_id":"101","register_pk":"108504","name":"旧松山家住宅松濤館（芦屋市立図書館打出分室）","kana":"きゅうまつやまけじゅうたくしょうとうかん（あしやしりつとしょかんうちでぶんしつ）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市打出小槌町2","lat":34.73319704,"lng":135.31506625,"geo_status":"db","era":"昭和5／平成2改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積150㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0383","desc":"敷地東寄りに建つ。鉄筋コンクリート造２階建、建築面積１５０㎡。東と北の外壁はルスティカ風に花崗岩を積み、重厚な外観とする。隅部は円弧状とし、２連アーチ窓を配し、軒にデンティルを施す。イタリア・ルネッサンス邸宅風の意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007522"},{"id":"00007523","register_sub_id":"101","register_pk":"108505","name":"旧松山家住宅塀","kana":"きゅうまつやまけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市打出小槌町2","lat":34.733446,"lng":135.31512251,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石垣、総延長36m","structure_material":"石垣","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0384","desc":"敷地の東辺、出入口を挟んで南北に延びる石垣で、折曲り総延長３６ｍ、高さ２ｍ内外である。基部を大振りな花崗岩の練積、その上に切石を帯状に置き、上部を玉石の練積とし、生垣を植える。閑静な住宅街に調和した景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007523"},{"id":"00008738","register_sub_id":"101","register_pk":"149459","name":"旧武藤家別邸洋館","kana":"きゅうむとうけべっていようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市垂水区東舞子町2051","lat":34.63012567,"lng":135.03628663,"geo_status":"db","era":"明治39年／平成8年・平成22年移築","year":1906,"year_source":"converted","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、スレート葺、建築面積168㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0513","desc":"北側道路に面して玄関を開き、海に面して円形平面のバルコニーを張り出す。木造2階建、建築面積168㎡。天然スレート葺で、寄棟や切妻を組み合わせた複雑な屋根を造る。花崗岩の切石積基礎に建ち、外壁は下見板張とする。質の高い意匠を有する景勝地の別荘。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008738"},{"id":"00007280","register_sub_id":"101","register_pk":"108262","name":"旧森家住宅（浜坂先人記念館以命亭）乾蔵","kana":"きゅうもりけじゅうたく（はまさかせんじんきねんかんいめいてい）いぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県美方郡新温泉町浜坂字本町1208","lat":35.625111,"lng":134.453491,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"28 － 0369","desc":"主屋の北西に位置する。桁行６．１ｍ梁間４．６ｍ、土蔵造２階建、切妻造、置屋根形式の桟瓦葺で、東妻に庇を付け、戸口とする。漆喰仕上げで、西・北面は高く押縁下見板張、南面は腰海鼠壁とする。２階の東妻面には庇付の窓を対で並べ、特徴的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007280"},{"id":"00007281","register_sub_id":"101","register_pk":"108263","name":"旧森家住宅（浜坂先人記念館以命亭）北ノ蔵","kana":"きゅうもりけじゅうたく（はまさかせんじんきねんかんいめいてい）きたのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県美方郡新温泉町浜坂字本町1208","lat":35.625099,"lng":134.453629,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"28 － 0370","desc":"敷地北辺、乾蔵の東側に建つ。桁行６．０ｍ梁間４．１ｍ、土蔵造２階建、切妻造、置屋根形式の桟瓦葺で、南面に両開戸を吊る。周囲は漆喰仕上げで、高く押縁下見板を張る。乾蔵と統一的な外観にまとめられ、敷地北辺の歴史的な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007281"},{"id":"00007279","register_sub_id":"101","register_pk":"108261","name":"旧森家住宅（浜坂先人記念館以命亭）主屋","kana":"きゅうもりけじゅうたく（はまさかせんじんきねんかんいめいてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県美方郡新温泉町浜坂字本町1208","lat":35.624992,"lng":134.453568,"geo_status":"db","era":"明治21／明治40増築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積279㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"28 － 0368","desc":"通り沿いの前庭に対して玄関を開き、西面して建つ。木造２階建、切妻造桟瓦葺で、北半部の棟を一段下げる。南寄りを通り土間とし、北に３列３行の座敷を設け、三方に縁をめぐらし、細部に繊細な意匠をみせる。正面は上下階とも格子をたて、風格のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007279"},{"id":"00014065","register_sub_id":"101","register_pk":"508325","name":"旧八木家住宅内蔵","kana":"きゅうやぎけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市余部区下余部字村中474-1","lat":34.79612222,"lng":134.57919444,"geo_status":"db","era":"弘化3年(1846)","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0770","desc":"主屋北西側に南面して建つ家財蔵。土蔵造二階建、切妻造本瓦葺で、かつては正面に下屋を付していた。外壁は軒先まで漆喰塗込で鉢巻付、正面腰を海鼠壁、他を竪板張とする。戸口に塗戸を吊り、各階板敷、登梁式の小屋組とする。主屋裏庭の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014065"},{"id":"00014062","register_sub_id":"101","register_pk":"508322","name":"旧八木家住宅主屋","kana":"きゅうやぎけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市余部区下余部字村中474-1","lat":34.79603056,"lng":134.57934444,"geo_status":"db","era":"江戸末期／明治前期、昭和35年頃・平成31年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積352㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0767","desc":"揖保川下流左岸の集落で大庄屋を務めた旧家の主屋。木造平屋建、入母屋造で南面し、西北に二階建の奥座敷を付す。正面側に下屋を付し、背面は屋根を葺下ろす。内部は東に土間、西に三列九室を配し、南西に床付座敷を配す。集落景観の中核をなす大型農家住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014062"},{"id":"00014064","register_sub_id":"101","register_pk":"508324","name":"旧八木家住宅蔵座敷","kana":"きゅうやぎけじゅうたくくらざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市余部区下余部字村中474-1","lat":34.79624722,"lng":134.57919444,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0769","desc":"敷地北辺に南面して建つ土蔵。土蔵造二階建、西を入母屋造の座敷、東を切妻造の土蔵とし、一体で本瓦葺とする。外壁は軒先まで漆喰塗込、腰を竪板張、土蔵正面腰を海鼠壁とする。座敷は藩吏接待用書院座敷、背面は旧水路に面し、大庄屋の屋敷構を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014064"},{"id":"00014063","register_sub_id":"101","register_pk":"508323","name":"旧八木家住宅米蔵","kana":"きゅうやぎけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市余部区下余部字村中474-1","lat":34.79617778,"lng":134.579375,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0768","desc":"蔵座敷東側に接続し、敷地北辺の旧水路沿いに南西向きに建つ年貢米の収蔵庫。土蔵造二階建、切妻造本瓦葺で、正面に下屋を付す。外壁は軒先まで漆喰塗込、正面腰を海鼠壁とし、他を竪板張とする。かつて水運が発達していた水路沿いの集落景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014063"},{"id":"00014066","register_sub_id":"101","register_pk":"508326","name":"旧八木家住宅長屋門","kana":"きゅうやぎけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市余部区下余部字村中474-1","lat":34.79584167,"lng":134.57943611,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積111㎡、脇塀付","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0771","desc":"敷地南辺中央に南面して建つ長屋門。入母屋造本瓦葺で中央西寄りに潜戸付の門口を開き、東に脇塀が延びる。外壁は漆喰で塗込め、正面に格子付窓を設けて腰を海鼠壁、他を竪板張とする。内部は西を旧勘定場、東を旧牛舎とする。旧家の表構を格式高く演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014066"},{"id":"00006719","register_sub_id":"101","register_pk":"107702","name":"旧山本家住宅（山本清記念財団会館）門衛所","kana":"きゅうやまもとけじゅうたく（やまもときよしきねんざいだんかいかん）もんえいじょ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市結善町3","lat":34.74649,"lng":135.331055,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡、脇門付","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"28 － 0296","desc":"通りに面して南北棟で建つ。桁行３．９ｍ梁間４．０ｍで、切妻造桟瓦葺とし、外壁は足下を鉄平石貼とするモルタル掻き落とし仕上げである。北に薄い水平のコンクリート版を出し、その下少し奥に鉄平石貼の壁を設け、扉を建てて脇門とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006719"},{"id":"00008565","register_sub_id":"101","register_pk":"134961","name":"日下家住宅石垣","kana":"くさかけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29730363,"lng":134.90699048,"geo_status":"db","era":"江戸後期／昭和前期・昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、延長109m","structure_material":"石造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0512","desc":"北に河川が流れる北下がりの土地に、石垣を築き、屋敷地を造る。総延長一〇九メートル、最も高い部分で五メートルに及ぶ。自然石乱積や間知石谷積ほか、石材や積み方などが場所によりさまざまに異なっており、当家の永い歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008565"},{"id":"00008559","register_sub_id":"101","register_pk":"134955","name":"日下家住宅井戸","kana":"くさかけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29711203,"lng":134.90710817,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造、面積0.5㎡","structure_material":"石造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0506","desc":"主屋の東、炊事場南の庭に位置する。長さ一・三メートル厚さ〇・一六メートル高さ〇・二七メートルの花崗岩を相欠で井形に組み、内法は〇・七メートル四方、高さは〇・五メートルとする。井戸の深さ四・一メートル。周囲を自然石で囲み、庭園の一部を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008559"}];
